  /**
   * Fuerza el volcado y sincronización de absolutamente todo el estado actual a Firebase.
   */
  async function syncAllToFirebase(notifyUser = true) {
    if (!db) {
      if (notifyUser) alert('⚠️ Firebase no está inicializado o no hay conexión.');
      return;
    }

    try {
      console.log('🔄 Iniciando sincronización completa con Firebase...');
      saveState();

      const collectionsMap = {
        'jugadores': state.directory?.jugadores || [],
        'clubes': state.directory?.clubes || [],
        'equipos': state.directory?.equipos || [],
        'federaciones': state.directory?.federaciones || [],
        'selecciones': state.directory?.selecciones || [],
        'convocatorias': state.directory?.convocatorias || [],
        'torneos': state.directory?.torneos || [],
        'staff': state.directory?.staff || [],
        'agencias': state.directory?.agencias || [],
        'agentes': state.directory?.agentes || [],
        'estadios': state.directory?.estadios || [],
        'partidos': state.matches || [],
        'informes': state.reports || [],
        'agenda': state.agenda || [],
        'agendaCategories': state.agendaCategories || [],
        'enlaces': state.links || []
      };

      setFirebaseHeaderStatus('syncing');
      for (const [colName, items] of Object.entries(collectionsMap)) {
        if (Array.isArray(items) && items.length > 0) {
          // Batch write in chunks of 450 to stay well under 500 limit
          for (let i = 0; i < items.length; i += 450) {
            const chunk = items.slice(i, i + 450);
            const batch = db.batch();
            chunk.forEach(item => {
              if (item && item.id) {
                markLocalWrite(colName, item.id);
                const ref = db.collection(colName).doc(String(item.id));
                batch.set(ref, item, { merge: true });
              }
            });
            await batch.commit();
          }
        }
      }

      const configToSave = Object.assign({}, state.settings || {}, {
        favColumns: state.favColumns || ['Columna 1', 'Columna 2', 'Columna 3'],
        customTabOrder: state.customTabOrder || [],
        dirTabOrder: state.dirTabOrder || [],
        agendaCategories: state.agendaCategories || [],
        cartelera: {
          priorityTeams: state.cartelera?.priorityTeams || [],
          interestingTeams: state.cartelera?.interestingTeams || []
        }
      });
      markLocalWrite('configuracion', 'app_settings');
      await db.collection('configuracion').doc('app_settings').set(configToSave, { merge: true });

      // Save Cartelera Calendars to their own collection
      if (state.cartelera && Array.isArray(state.cartelera.calendarios)) {
        for (let i = 0; i < state.cartelera.calendarios.length; i += 450) {
          const chunk = state.cartelera.calendarios.slice(i, i + 450);
          const batch = db.batch();
          chunk.forEach(cal => {
            if (cal && cal.id) {
              markLocalWrite('cartelera_calendarios', cal.id);
              const ref = db.collection('cartelera_calendarios').doc(String(cal.id));
              batch.set(ref, cal, { merge: true });
            }
          });
          await batch.commit();
        }
      }

      console.log('✅ Sincronización completa finalizada en Firebase');
      setFirebaseHeaderStatus('synced');
      if (notifyUser) {
        if (typeof showToast === 'function') {
          showToast('☁️ Sincronización con Firebase completada con éxito', 'success');
        } else {
          alert('☁️ Sincronización con Firebase completada con éxito');
        }
      }
    } catch (err) {
      console.error('Error durante la sincronización a Firebase:', err);
      if (notifyUser) alert('⚠️ Error al sincronizar con Firebase: ' + err.message);
    }
  }

  /**
   * Carga la base de datos de Firebase desde todas las colecciones.
   */
  async function loadFromFirebase() {
    if (!db) return false;
    try {
      console.log('📡 Consultando colecciones de Firebase Firestore...');

      const fetchCol = async (colName) => {
        try {
          const snap = await db.collection(colName).get();
          const docs = [];
          snap.forEach(doc => docs.push(doc.data()));
          return docs;
        } catch (e) {
          console.warn(`Error al consultar ${colName}:`, e);
          return [];
        }
      };

      const [
        jugadores, clubes, equipos, federaciones, selecciones,
        convocatorias, torneos, staff, agencias, agentes, estadios,
        partidos, informes, agenda, agendaCategories, enlaces, cartelera_calendarios
      ] = await Promise.all([
        fetchCol('jugadores'),
        fetchCol('clubes'),
        fetchCol('equipos'),
        fetchCol('federaciones'),
        fetchCol('selecciones'),
        fetchCol('convocatorias'),
        fetchCol('torneos'),
        fetchCol('staff'),
        fetchCol('agencias'),
        fetchCol('agentes'),
        fetchCol('estadios'),
        fetchCol('partidos'),
        fetchCol('informes'),
        fetchCol('agenda'),
        fetchCol('agendaCategories'),
        fetchCol('enlaces'),
        fetchCol('cartelera_calendarios')
      ]);

      let configData = null;
      try {
        const configSnap = await db.collection('configuracion').doc('app_settings').get();
        if (configSnap.exists) {
          configData = configSnap.data();
        }
      } catch (e) { }

      const totalItemsCloud = jugadores.length + clubes.length + equipos.length + federaciones.length +
        selecciones.length + convocatorias.length + torneos.length + staff.length + agencias.length +
        agentes.length + estadios.length + partidos.length + informes.length + agenda.length + enlaces.length;

      if (totalItemsCloud > 0) {
        console.log(`🔥 Se obtuvieron ${totalItemsCloud} registros desde Firebase Cloud Firestore`);

        state.directory = state.directory || {};
        if (Array.isArray(jugadores) && jugadores.length > 0) state.directory.jugadores = jugadores;
        if (Array.isArray(clubes) && clubes.length > 0) state.directory.clubes = clubes;
        if (Array.isArray(equipos) && equipos.length > 0) state.directory.equipos = equipos;
        if (Array.isArray(federaciones) && federaciones.length > 0) state.directory.federaciones = federaciones;
        if (Array.isArray(selecciones) && selecciones.length > 0) state.directory.selecciones = selecciones;
        if (Array.isArray(convocatorias) && convocatorias.length > 0) state.directory.convocatorias = convocatorias;
        if (Array.isArray(torneos) && torneos.length > 0) state.directory.torneos = torneos;
        if (Array.isArray(staff) && staff.length > 0) state.directory.staff = staff;
        if (Array.isArray(agencias) && agencias.length > 0) state.directory.agencias = agencias;
        if (Array.isArray(agentes) && agentes.length > 0) state.directory.agentes = agentes;
        if (Array.isArray(estadios) && estadios.length > 0) state.directory.estadios = estadios;

        state.matches = (Array.isArray(partidos) && partidos.length > 0) ? partidos : (state.matches || []);
        state.reports = (Array.isArray(informes) && informes.length > 0) ? informes : (state.reports || []);
        state.agenda = (Array.isArray(agenda) && agenda.length > 0) ? agenda : (state.agenda || []);
        if (Array.isArray(agendaCategories) && agendaCategories.length > 0) {
          state.agendaCategories = agendaCategories;
        } else if (configData && Array.isArray(configData.agendaCategories) && configData.agendaCategories.length > 0) {
          state.agendaCategories = configData.agendaCategories;
        }
        if (configData && configData.cartelera) {
          state.cartelera = configData.cartelera;
        } else {
          ensureCarteleraState();
        }
        if (Array.isArray(cartelera_calendarios) && cartelera_calendarios.length > 0) {
          state.cartelera.calendarios = cartelera_calendarios;
        }

        if (typeof renderCartelera === 'function') renderCartelera();
        if (Array.isArray(configData?.notifications)) {
          state.notifications = configData.notifications;
          if (typeof renderNotificationsUI === 'function') renderNotificationsUI();
        }
        state.links = (Array.isArray(enlaces) && enlaces.length > 0) ? enlaces : (state.links || []);

        if (configData) {
          state.settings = Object.assign({}, state.settings, configData);
          if (configData.appName) {
            state.settings.appName = configData.appName;
            try {
              localStorage.setItem(APP_NAME_STORAGE_KEY, configData.appName);
            } catch (e) { }
            updateAppNameUI(configData.appName);
          }
          if (Array.isArray(configData.favColumns) && configData.favColumns.length > 0) {
            state.favColumns = configData.favColumns;
          }
          if (Array.isArray(configData.customTabOrder)) {
            state.customTabOrder = configData.customTabOrder;
          }
          if (Array.isArray(configData.dirTabOrder)) {
            state.dirTabOrder = configData.dirTabOrder;
          }
          if (Array.isArray(configData.customClubTypes) && configData.customClubTypes.length > 0) {
            state.customClubTypes = Array.from(new Set([...(state.customClubTypes || []), ...configData.customClubTypes]));
          }
          if (configData.clubesNavarraSeeded) state.directory.clubesNavarraSeeded = true;
          if (configData.federacionesSeeded) state.directory.federacionesSeeded = true;
          if (configData.clubesAragonSeeded) state.directory.clubesAragonSeeded = true;
          if (configData.equiposAragonSeeded) state.directory.equiposAragonSeeded = true;
          if (configData.federacionesSeleccionesSeeded) state.directory.federacionesSeleccionesSeeded = true;
          if (Array.isArray(configData.directoryFederationsOrder)) state.directoryFederationsOrder = configData.directoryFederationsOrder;
          if (Array.isArray(configData.directoryCategoriesOrder)) state.directoryCategoriesOrder = configData.directoryCategoriesOrder;
          if (configData.deletedTombstones && typeof configData.deletedTombstones === 'object') state.deletedTombstones = configData.deletedTombstones;
          if (configData.federacionesClubsMigrated) state.directory.federacionesClubsMigrated = true;
          if (configData.aragonWiped) state.directory.aragonWiped = true;
          if (configData.navarraLnjSeeded) state.directory.navarraLnjSeeded = true;
          if (configData.navarraTerceraSeeded) state.directory.navarraTerceraSeeded = true;
          if (configData.navarraAutonomicaSeeded) state.directory.navarraAutonomicaSeeded = true;
          if (configData.navarraPrimeraAutonomicaJuvenilSeeded) state.directory.navarraPrimeraAutonomicaJuvenilSeeded = true;
          if (configData.navarraRegionalPreferenteSeeded) state.directory.navarraRegionalPreferenteSeeded = true;
          if (configData.navarraRegionalPreferenteG2Seeded) state.directory.navarraRegionalPreferenteG2Seeded = true;
          if (configData.navarraLigaCadeteSeeded) state.directory.navarraLigaCadeteSeeded = true;
          if (configData.navarraPrimeraAutonomicaCadeteSeeded) state.directory.navarraPrimeraAutonomicaCadeteSeeded = true;
          if (configData.navarraPrimeraRegionalG1Seeded) state.directory.navarraPrimeraRegionalG1Seeded = true;
          if (configData.navarraPrimeraRegionalG2Seeded) state.directory.navarraPrimeraRegionalG2Seeded = true;
          if (configData.navarraPrimeraRegionalG3Seeded) state.directory.navarraPrimeraRegionalG3Seeded = true;
          if (configData.navarraPrimeraRegionalG4Seeded) state.directory.navarraPrimeraRegionalG4Seeded = true;
          if (configData.navarraPrimeraRegionalG5Seeded) state.directory.navarraPrimeraRegionalG5Seeded = true;
          if (configData.dhjGroup3Seeded) state.directory.dhjGroup3Seeded = true;
          if (configData.dhjGroup2Seeded) state.directory.dhjGroup2Seeded = true;
        }

        setFirebaseHeaderStatus('synced');

        // Run seeding and migrations to ensure directory is completely populated
        // Seeding and migrations removed per user request

        if (typeof renderAllViews === 'function') {
          renderAllViews();
        }
        return true;
      } else {
        console.log('ℹ️ Firebase no contiene colecciones de datos. Sincronizando estado local inicial a Firebase...');
        return false;
      }
    } catch (err) {
      console.warn('Error al cargar colecciones de Firebase:', err);
      return false;
    }
  }

  function initFirebaseRealtimeListener() {
    if (!db) return;

    console.log('📡 Iniciando escuchas en tiempo real (onSnapshot)...');

    // 1. Escuchar la configuración global (incluyendo el estado de la UI)
    db.collection('configuracion').doc('app_settings').onSnapshot(doc => {
      if (isRecentLocalWrite('configuracion', 'app_settings')) return;

      if (doc.exists) {
        const configData = doc.data();
        if (configData) {
          state.settings = Object.assign({}, state.settings, configData);
          if (configData.appName) {
            state.settings.appName = configData.appName;
            try { localStorage.setItem(APP_NAME_STORAGE_KEY, configData.appName); } catch (e) { }
            updateAppNameUI(configData.appName);
          }
          if (Array.isArray(configData.favColumns) && configData.favColumns.length > 0) state.favColumns = configData.favColumns;
          if (Array.isArray(configData.customTabOrder)) state.customTabOrder = configData.customTabOrder;
          if (Array.isArray(configData.dirTabOrder)) state.dirTabOrder = configData.dirTabOrder;
          if (Array.isArray(configData.customClubTypes) && configData.customClubTypes.length > 0) {
            state.customClubTypes = Array.from(new Set([...(state.customClubTypes || []), ...configData.customClubTypes]));
          }
          if (configData.clubesNavarraSeeded) state.directory.clubesNavarraSeeded = true;
          if (configData.federacionesSeeded) state.directory.federacionesSeeded = true;
          if (configData.clubesAragonSeeded) state.directory.clubesAragonSeeded = true;
          if (configData.equiposAragonSeeded) state.directory.equiposAragonSeeded = true;
          if (configData.federacionesSeleccionesSeeded) state.directory.federacionesSeleccionesSeeded = true;
          if (Array.isArray(configData.directoryFederationsOrder)) state.directoryFederationsOrder = configData.directoryFederationsOrder;
          if (Array.isArray(configData.directoryCategoriesOrder)) state.directoryCategoriesOrder = configData.directoryCategoriesOrder;
          if (configData.deletedTombstones && typeof configData.deletedTombstones === 'object') state.deletedTombstones = configData.deletedTombstones;

          if (configData.cartelera) {
            // Merge teams from config (calendarios are handled separately now)
            state.cartelera.priorityTeams = configData.cartelera.priorityTeams || [];
            state.cartelera.interestingTeams = configData.cartelera.interestingTeams || [];
          }
          if (Array.isArray(configData.notifications)) {
            state.notifications = configData.notifications;
          }

          if (typeof renderAllViews === 'function') renderAllViews();
        }
      }
    }, err => {
      console.error('Error escuchando configuracion:', err);
    });

    // 2. Factory genérico para escuchar colecciones
    const listenCollection = (colName, arrayGetter, arraySetter) => {
      db.collection(colName).onSnapshot(snap => {
        let currentArray = arrayGetter() || [];
        let hasChanges = false;

        snap.docChanges().forEach(change => {
          const docId = change.doc.id;
          const data = { id: docId, ...change.doc.data() };

          if (isRecentLocalWrite(colName, docId)) return; // Anti-echo

          hasChanges = true;

          if (change.type === 'added' || change.type === 'modified') {
            const idx = currentArray.findIndex(item => String(item.id) === String(docId) || String(item.codigo) === String(docId));
            if (idx !== -1) {
              currentArray[idx] = data;
            } else {
              currentArray.push(data);
            }
          } else if (change.type === 'removed') {
            currentArray = currentArray.filter(item => String(item.id) !== String(docId) && String(item.codigo) !== String(docId));
          }
        });

        if (hasChanges) {
          arraySetter(currentArray);
          if (typeof renderAllViews === 'function') renderAllViews();
        }
      }, err => {
        console.error(`Error escuchando ${colName}:`, err);
      });
    };

    // 3. Conectar todas las colecciones al estado
    state.directory = state.directory || {};

    listenCollection('jugadores', () => state.directory.jugadores, arr => state.directory.jugadores = arr);
    listenCollection('clubes', () => state.directory.clubes, arr => state.directory.clubes = arr);
    listenCollection('equipos', () => state.directory.equipos, arr => state.directory.equipos = arr);
    listenCollection('federaciones', () => state.directory.federaciones, arr => state.directory.federaciones = arr);
    listenCollection('selecciones', () => state.directory.selecciones, arr => state.directory.selecciones = arr);
    listenCollection('convocatorias', () => state.directory.convocatorias, arr => state.directory.convocatorias = arr);
    listenCollection('torneos', () => state.directory.torneos, arr => state.directory.torneos = arr);
    listenCollection('staff', () => state.directory.staff, arr => state.directory.staff = arr);
    listenCollection('agencias', () => state.directory.agencias, arr => state.directory.agencias = arr);
    listenCollection('agentes', () => state.directory.agentes, arr => state.directory.agentes = arr);
    listenCollection('estadios', () => state.directory.estadios, arr => state.directory.estadios = arr);

    listenCollection('partidos', () => state.matches, arr => state.matches = arr);
    listenCollection('informes', () => state.reports, arr => state.reports = arr);
    listenCollection('agenda', () => state.agenda, arr => state.agenda = arr);
    listenCollection('enlaces', () => state.links, arr => state.links = arr);

    // Escucha para la nueva colección de calendarios de la cartelera
    state.cartelera = state.cartelera || { calendarios: [], priorityTeams: [], interestingTeams: [] };
    if (!state.cartelera.interestingTeams) state.cartelera.interestingTeams = [];
    listenCollection('cartelera_calendarios', () => state.cartelera.calendarios, arr => state.cartelera.calendarios = arr);

    // Carga inicial (fallback for seeding si las colecciones están vacías)
    loadFromFirebase();
  }

