  function findTeamInDirectory(teamName) {
    if (!teamName || typeof teamName !== 'string') return null;
    const query = teamName.trim().toLowerCase();
    if (!query) return null;

    const equipos = state.directory.equipos || [];
    const selecciones = state.directory.selecciones || [];

    // 1. Exact match in equipos
    let found = equipos.find(e => {
      const n = (e.nombre || e.equipo || '').toLowerCase();
      return n && n === query;
    });
    if (found) return found;

    // 2. Exact match in selecciones
    found = selecciones.find(s => {
      const n = (s.nombre || s.seleccion || '').toLowerCase();
      return n && n === query;
    });
    if (found) return found;

    // 3. Substring / Partial match in equipos
    found = equipos.find(e => {
      const n = (e.nombre || e.equipo || '').toLowerCase();
      return n && (query.includes(n) || n.includes(query));
    });
    if (found) return found;

    // 4. Substring / Partial match in selecciones
    found = selecciones.find(s => {
      const n = (s.nombre || s.seleccion || '').toLowerCase();
      return n && (query.includes(n) || n.includes(query));
    });
    if (found) return found;

    // 5. Normalized search (ignoring dots, hyphens, extra spaces)
    const norm = (str) => str.toLowerCase().replace(/[\.\,\-]/g, '').replace(/\s+/g, ' ').trim();
    const queryNorm = norm(query);

    found = equipos.find(e => {
      const nNorm = norm(e.nombre || e.equipo || '');
      return nNorm && (queryNorm.includes(nNorm) || nNorm.includes(queryNorm));
    });
    if (found) return found;

    return null;
  }

  function areColorsSimilar(hex1, hex2) {
    if (!hex1 || !hex2) return false;
    let h1 = hex1.replace('#', '');
    let h2 = hex2.replace('#', '');
    if (h1.length === 3) h1 = h1.split('').map(c => c + c).join('');
    if (h2.length === 3) h2 = h2.split('').map(c => c + c).join('');
    if (h1.length !== 6 || h2.length !== 6) return false;

    const r1 = parseInt(h1.substr(0, 2), 16);
    const g1 = parseInt(h1.substr(2, 2), 16);
    const b1 = parseInt(h1.substr(4, 2), 16);

    const r2 = parseInt(h2.substr(0, 2), 16);
    const g2 = parseInt(h2.substr(2, 2), 16);
    const b2 = parseInt(h2.substr(4, 2), 16);

    // Euclidean distance in RGB space
    const dist = Math.sqrt(Math.pow(r2 - r1, 2) + Math.pow(g2 - g1, 2) + Math.pow(b2 - b1, 2));

    // A distance < 120 means colors are reasonably similar visually.
    return dist < 120;
  }

  function distributePlayersToSlots(squadPlayers, slotPositions) {
    // Build a map: slotIndex -> [] of player objects
    const slotMap = {};
    slotPositions.forEach((_, idx) => { slotMap[idx] = []; });

    // Track which players have already been assigned to a slot
    const assignedPlayerIds = new Set();

    // Helper: check if a player position matches a slot code
    function posMatchesSlot(posStr, slotCode) {
      if (!posStr || !slotCode) return false;
      const p = posStr.toUpperCase().trim();
      const s = slotCode.toUpperCase().trim();
      return p === s;
    }

    // PASS 1: Exact primary-position matches only
    slotPositions.forEach((posCode, idx) => {
      squadPlayers.forEach(p => {
        if (assignedPlayerIds.has(p.id)) return;
        const pPrimary = (p.posicionPrincipal || p.posicion || '').toUpperCase().trim();
        if (posMatchesSlot(pPrimary, posCode)) {
          slotMap[idx].push(p);
          assignedPlayerIds.add(p.id);
        }
      });
    });

    // PASS 2: Fuzzy primary-position matches (e.g. MC matches MCD slot if no exact)
    slotPositions.forEach((posCode, idx) => {
      if (slotMap[idx].length > 0) return; // slot already has players
      const codeUpper = posCode.toUpperCase().trim();
      squadPlayers.forEach(p => {
        if (assignedPlayerIds.has(p.id)) return;
        const pPrimary = (p.posicionPrincipal || p.posicion || '').toUpperCase().trim();
        if (pPrimary && (pPrimary.includes(codeUpper) || codeUpper.includes(pPrimary))) {
          slotMap[idx].push(p);
          assignedPlayerIds.add(p.id);
        }
      });
    });

    // PASS 3: Redistribute overcrowded slots — move extras to secondary position slots
    // If a slot has 3+ players, try to move players whose secondary position matches
    // another slot that has fewer players
    const MAX_PER_SLOT = 2;
    let changed = true;
    let iterations = 0;
    while (changed && iterations < 10) {
      changed = false;
      iterations++;
      slotPositions.forEach((posCode, idx) => {
        while (slotMap[idx].length > MAX_PER_SLOT) {
          // Try to move one player to another slot via secondary position
          let moved = false;
          for (let pi = slotMap[idx].length - 1; pi >= 0; pi--) {
            const player = slotMap[idx][pi];
            const secPos = (player.posicionSecundaria || '').toUpperCase().trim();
            if (!secPos) continue;

            // Find a target slot that matches the secondary position and has fewer players
            for (let targetIdx = 0; targetIdx < slotPositions.length; targetIdx++) {
              if (targetIdx === idx) continue;
              const targetCode = slotPositions[targetIdx].toUpperCase().trim();
              if (posMatchesSlot(secPos, targetCode) && slotMap[targetIdx].length < MAX_PER_SLOT) {
                // Move player to target slot
                slotMap[idx].splice(pi, 1);
                slotMap[targetIdx].push(player);
                moved = true;
                changed = true;
                break;
              }
            }
            if (moved) break;
          }
          // Also try fuzzy secondary match if exact didn't work
          if (!moved) {
            for (let pi = slotMap[idx].length - 1; pi >= 0; pi--) {
              const player = slotMap[idx][pi];
              const secPos = (player.posicionSecundaria || '').toUpperCase().trim();
              if (!secPos) continue;
              for (let targetIdx = 0; targetIdx < slotPositions.length; targetIdx++) {
                if (targetIdx === idx) continue;
                const targetCode = slotPositions[targetIdx].toUpperCase().trim();
                if ((secPos.includes(targetCode) || targetCode.includes(secPos)) && slotMap[targetIdx].length < MAX_PER_SLOT) {
                  slotMap[idx].splice(pi, 1);
                  slotMap[targetIdx].push(player);
                  moved = true;
                  changed = true;
                  break;
                }
              }
              if (moved) break;
            }
          }
          if (!moved) break; // Can't redistribute further, stop
        }
      });
    }

    // PASS 4: Assign remaining unassigned players via their secondary position
    squadPlayers.forEach(p => {
      if (assignedPlayerIds.has(p.id)) return;
      const secPos = (p.posicionSecundaria || '').toUpperCase().trim();
      if (!secPos) return;
      for (let idx = 0; idx < slotPositions.length; idx++) {
        const slotCode = slotPositions[idx].toUpperCase().trim();
        if (posMatchesSlot(secPos, slotCode) && slotMap[idx].length < MAX_PER_SLOT) {
          slotMap[idx].push(p);
          assignedPlayerIds.add(p.id);
          return;
        }
      }
      // Fuzzy secondary
      for (let idx = 0; idx < slotPositions.length; idx++) {
        const slotCode = slotPositions[idx].toUpperCase().trim();
        if ((secPos.includes(slotCode) || slotCode.includes(secPos)) && slotMap[idx].length < MAX_PER_SLOT) {
          slotMap[idx].push(p);
          assignedPlayerIds.add(p.id);
          return;
        }
      }
    });

    return slotMap;
  }

  function formatPlayerNameForCampograma(fullName) {
    if (!fullName) return "";
    const parts = fullName.trim().split(/\s+/);
    if (parts.length === 1) return parts[0];
    return parts[0] + " " + parts[1];
  }

  function getContrastColor(hexColor) {
    if (!hexColor || typeof hexColor !== 'string') return '#ffffff';
    let hex = hexColor.replace('#', '');
    if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
    if (hex.length !== 6) return '#ffffff';
    const r = parseInt(hex.substr(0, 2), 16);
    const g = parseInt(hex.substr(2, 2), 16);
    const b = parseInt(hex.substr(4, 2), 16);
    const yiq = ((r * 299) + (g * 587) + (b * 114)) / 1000;
    return (yiq >= 128) ? '#000000' : '#ffffff';
  }

  function findCoachForTeam(teamName) {
    if (!teamName || !state.directory) return '';
    if (state.directory.staff && Array.isArray(state.directory.staff)) {
      const foundStaff = state.directory.staff.find(s => {
        const t = (s.equipo || s.team || '').trim().toLowerCase();
        const tn = teamName.trim().toLowerCase();
        const teamMatch = t && tn && (t === tn || (t.length > 3 && tn.includes(t)) || (tn.length > 3 && t.includes(tn)));
        const cargo = (s.cargo || s.puesto || '').toUpperCase();
        const isCoach = !cargo || cargo.includes('ENTRENADOR') || cargo.includes('TÉCNICO') || cargo.includes('COACH');
        return teamMatch && isCoach;
      });
      if (foundStaff) return foundStaff.nombre || foundStaff.staff || '';
    }
    const teamObj = findTeamInDirectory(teamName);
    if (teamObj && (teamObj.entrenador || teamObj.tecnico || teamObj.entrenadorPrincipal)) {
      return teamObj.entrenador || teamObj.tecnico || teamObj.entrenadorPrincipal;
    }
    return '';
  }

  function findAllCoachesForTeam(teamName) {
    if (!teamName || !state.directory) return [];
    let coaches = [];
    if (state.directory.staff && Array.isArray(state.directory.staff)) {
      coaches = state.directory.staff.filter(s => {
        const t = (s.equipo || s.team || '').trim().toLowerCase();
        const tn = teamName.trim().toLowerCase();
        const teamMatch = t && tn && (t === tn || (t.length > 3 && tn.includes(t)) || (tn.length > 3 && t.includes(tn)));
        const cargo = (s.cargo || s.puesto || '').toUpperCase();
        const isCoach = !cargo || cargo.includes('ENTRENADOR') || cargo.includes('TÉCNICO') || cargo.includes('COACH');
        return teamMatch && isCoach;
      }).map(s => s.nombre || s.staff || '').filter(Boolean);
    }
    const teamObj = findTeamInDirectory(teamName);
    if (teamObj && (teamObj.entrenador || teamObj.tecnico || teamObj.entrenadorPrincipal)) {
      const tCoach = teamObj.entrenador || teamObj.tecnico || teamObj.entrenadorPrincipal;
      if (!coaches.includes(tCoach)) coaches.push(tCoach);
    }
    return coaches;
  }

  function updateMatchTeamBadgeAndColor(team, isInit = false) {
    const teamInput = document.getElementById(team === 'local' ? 'reportLocalTeam' : 'reportVisitanteTeam');
    const badgeLabel = document.getElementById(`${team}TeamBadge`);
    if (!teamInput || !badgeLabel) return;

    const teamName = teamInput.value.trim();
    const teamObj = findTeamInDirectory(teamName);

    // Auto-fill or clear Coach
    const coachInput = document.getElementById(team === 'local' ? 'localEntrenador' : 'visitanteEntrenador');
    if (coachInput) {
      if (!isInit) coachInput.value = ''; // Vaciar al cambiar equipo, para que no arrastre de otro

      const coachName = findCoachForTeam(teamName);
      if (coachName && (!isInit || !coachInput.value)) {
        coachInput.value = coachName;
      }

      // Update Datalist
      const datalist = document.getElementById(`${team}CoachDatalist`);
      if (datalist) {
        const coaches = findAllCoachesForTeam(teamName);
        datalist.innerHTML = coaches.map(c => `<option value="${escapeHtml(c)}"></option>`).join('');
      }
    }

    let badgeSrc = '';
    if (teamObj) {
      badgeSrc = teamObj.escudo || teamObj.foto || teamObj.imagen || '';
      if (!badgeSrc && teamObj.federacion && typeof FEDERACIONES_LOGOS !== 'undefined' && FEDERACIONES_LOGOS[teamObj.federacion]) {
        badgeSrc = FEDERACIONES_LOGOS[teamObj.federacion];
      }

      // Auto-fill competition, category, federation and stadium from Local team profile
      if (team === 'local') {
        const compVal = teamObj.liga || teamObj.competicion || '';
        const catVal = teamObj.categoria || '';
        const fedVal = teamObj.federacion || '';
        const estVal = teamObj.estadio || teamObj.estadioVinculado || '';

        const compInput = document.getElementById('reportCompeticion');
        const catInput = document.getElementById('reportCategoria');
        const fedInput = document.getElementById('reportFederacion');
        const estInput = document.getElementById('reportEstadio');

        if (!isInit) {
          if (compVal && compInput) compInput.value = compVal;
          if (catVal && catInput) catInput.value = catVal;
          if (fedVal && fedInput) fedInput.value = fedVal;
          if (estVal && estInput) estInput.value = estVal;
        } else {
          if (compVal && compInput && !compInput.value) compInput.value = compVal;
          if (catVal && catInput && !catInput.value) catInput.value = catVal;
          if (fedVal && fedInput && !fedInput.value) fedInput.value = fedVal;
          if (estVal && estInput && !estInput.value) estInput.value = estVal;
        }
      }
    }

    if (badgeSrc) {
      badgeLabel.innerHTML = `<img src="${badgeSrc}" style="width: 32px; height: 32px; object-fit: contain; border-radius: 4px;">`;
    } else {
      badgeLabel.innerHTML = `<i data-lucide="shield" style="width: 24px; height: 24px;"></i>`;
      if (window.lucide) window.lucide.createIcons();
    }

    // Auto-fill player names based on dorsals if team changes
    if (teamName) {
      const containers = [
        document.getElementById(`${team}TitularesRows`),
        document.getElementById(`${team}SuplentesRows`)
      ];
      containers.forEach(container => {
        if (!container) return;
        container.querySelectorAll('.lineup-row').forEach(row => {
          const numInput = row.querySelector('input.num');
          const nameInput = row.querySelector('input.name');
          const posSelect = row.querySelector('select.pos');
          if (numInput && numInput.value && nameInput && !nameInput.value.trim()) {
            const matchedPlayer = findPlayerByTeamAndDorsal(teamName, numInput.value);
            if (matchedPlayer) {
              nameInput.value = matchedPlayer.nombre || matchedPlayer.jugador || matchedPlayer.name || '';
              const matchedPos = matchedPlayer.posicionPrincipal || matchedPlayer.posicion || matchedPlayer.pos || '';
              if (posSelect && matchedPos) {
                const optExists = Array.from(posSelect.options).some(opt => opt.value === matchedPos);
                if (optExists) posSelect.value = matchedPos;
                else {
                  const newOpt = document.createElement('option');
                  newOpt.value = matchedPos;
                  newOpt.textContent = matchedPos;
                  newOpt.selected = true;
                  posSelect.appendChild(newOpt);
                }
              }
            }
          }
        });
      });
    }

    renderPitchPins(team);
    if (typeof updateTeamPlayersDatalist === 'function') {
      updateTeamPlayersDatalist(team);
    }
  }

