  function buildFilteredPerfilRSHTML(pPos) {
    const normPos = (pPos || '').toUpperCase().trim();
    const groupKey = POSITION_TO_PERFIL_GROUP[normPos];

    if (groupKey && OPTIONS_PERFIL_RS[groupKey]) {
      let html = `<option value="">+ Añadir perfil RS (${groupKey})...</option>`;
      html += `<optgroup label="${escapeHtml(groupKey)}">`;
      OPTIONS_PERFIL_RS[groupKey].forEach(item => {
        html += `<option value="${escapeHtml(item)}">${escapeHtml(item)}</option>`;
      });
      html += `</optgroup>`;
      return html;
    }

    return buildOptgroupsHTML(OPTIONS_PERFIL_RS, 'Añadir perfil RS...');
  }

  function buildOptgroupsHTML(optionsObj, placeholder) {
    let html = `<option value="">+ ${escapeHtml(placeholder)}</option>`;
    for (const [groupLabel, items] of Object.entries(optionsObj)) {
      html += `<optgroup label="${escapeHtml(groupLabel)}">`;
      items.forEach(item => {
        html += `<option value="${escapeHtml(item)}">${escapeHtml(item)}</option>`;
      });
      html += `</optgroup>`;
    }
    return html;
  }

  function buildKeepOpenDropdownHTML(optionsObj, placeholder, targetId) {
    let html = `
    <div class="custom-dropdown-wrapper" style="position: relative; width: 100%; margin-bottom: 0;">
      <div class="form-control select-compact custom-dropdown-header" style="height: 38px; box-sizing: border-box; cursor: pointer; display: flex; justify-content: space-between; align-items: center; background: #fff;" onclick="event.stopPropagation(); const m = this.nextElementSibling; if(m.classList.contains('hidden')){ document.querySelectorAll('.custom-dropdown-menu').forEach(x=>x.classList.add('hidden')); m.classList.remove('hidden'); const textarea = document.getElementById('${escapeHtml(targetId)}'); if(textarea){ const parts = textarea.value.split(',').map(s=>s.trim()).filter(Boolean); m.querySelectorAll('.custom-dropdown-item').forEach(i => { if(parts.includes(i.dataset.val)){ i.innerHTML = '${escapeHtml(placeholder).replace(/'/g, "\\'")}' ? i.dataset.val + ' <i data-lucide=\\'check\\' style=\\'width:14px; height:14px; color:var(--primary-color); float:right;\\'></i>' : i.dataset.val; } else { i.innerHTML = i.dataset.val; } }); if(window.lucide) window.lucide.createIcons(); } } else { m.classList.add('hidden'); }">
        <span>+ ${escapeHtml(placeholder)}</span>
        <i data-lucide="chevron-down" style="width: 14px; height: 14px;"></i>
      </div>
      <div class="custom-dropdown-menu hidden" style="position: absolute; top: 100%; left: 0; right: 0; z-index: 100; max-height: 200px; overflow-y: auto; background: #fff; border: 1px solid var(--border-medium); border-radius: var(--radius-md); box-shadow: var(--shadow-md);">
    `;

    // Opción para crear uno nuevo dinámicamente
    html += `<div style="padding: 8px 12px; cursor: pointer; font-size: 12px; color: var(--primary-blue); font-weight: 700; border-bottom: 2px solid var(--border-light); background: #f0f9ff; display: flex; align-items: center; gap: 6px;" onmouseover="this.style.background='#e0f2fe'" onmouseout="this.style.background='#f0f9ff'" onclick="event.stopPropagation(); const val = prompt('Introduce la nueva descripción:'); if(val && val.trim()){ const t = document.getElementById('${escapeHtml(targetId)}'); if(t){ const parts = t.value.split(',').map(s=>s.trim()).filter(Boolean); if(!parts.includes(val.trim())){ parts.push(val.trim()); t.value = parts.join(', '); t.dispatchEvent(new Event('input', { bubbles: true })); } } this.parentElement.classList.add('hidden'); }">+ Crear nuevo...</div>`;

    for (const [groupLabel, items] of Object.entries(optionsObj)) {
      html += `<div style="padding: 6px 12px; font-weight: 800; font-size: 11px; background: var(--bg-subtle); color: var(--text-muted); text-transform: uppercase; position: sticky; top: 0; z-index: 1;">${escapeHtml(groupLabel)}</div>`;

      const sortedItems = [...items].sort((a, b) => a.localeCompare(b, 'es'));

      sortedItems.forEach(item => {
        html += `<div class="custom-dropdown-item" data-val="${escapeHtml(item)}" data-target="${escapeHtml(targetId)}" style="padding: 6px 16px; cursor: pointer; font-size: 12px; transition: background 0.2s; border-bottom: 1px solid var(--border-light); display: flex; justify-content: space-between; align-items: center;" onmouseover="this.style.background='var(--bg-subtle)'" onmouseout="this.style.background='transparent'">${escapeHtml(item)}</div>`;
      });
    }
    html += `</div></div>`;
    return html;
  }

  function buildFilteredPerfilKeepOpenHTML(pos, targetId) {
    let filteredObj = {};
    const normPos = (pos || '').toUpperCase().trim();
    const groupKey = POSITION_TO_PERFIL_GROUP[normPos];

    if (groupKey && OPTIONS_PERFIL_RS[groupKey]) {
      filteredObj[groupKey] = OPTIONS_PERFIL_RS[groupKey];
    } else {
      filteredObj = OPTIONS_PERFIL_RS;
    }
    return buildKeepOpenDropdownHTML(filteredObj, 'Añadir perfil RS...', targetId);
  }

  function getCurrentMatchMinute() {
    if (typeof timerSeconds === 'number' && timerSeconds > 0) {
      return Math.min(90, Math.max(1, Math.floor(timerSeconds / 60)));
    }
    return 0;
  }

  function syncPlayerMatchReportToDirectory(pName, pNum, teamName, evalData) {
    if (!pName || !state.directory || !state.directory.jugadores) return;

    // Find matching player in directory by name or dorsal+team
    const playerInDir = state.directory.jugadores.find(p => {
      const nameMatch = p.nombre && p.nombre.toLowerCase().trim() === pName.toLowerCase().trim();
      const numMatch = String(p.dorsal || p.numero || '').trim() === String(pNum).trim();
      const teamMatch = p.equipo && teamName && window.flexibleMatch(teamName, p.equipo);
      return nameMatch || (numMatch && teamMatch);
    });

    if (playerInDir) {
      function mergeUniqueCsv(oldStr, newStr) {
        if (!oldStr) return newStr || '';
        if (!newStr) return oldStr || '';
        const set = new Set([...oldStr.split(','), ...newStr.split(',')].map(s => s.trim()).filter(s => s));
        return Array.from(set).join(', ');
      }

      if (evalData.descFisica) playerInDir.descFisica = mergeUniqueCsv(playerInDir.descFisica, evalData.descFisica);
      if (evalData.descTecnica) playerInDir.descTecnica = mergeUniqueCsv(playerInDir.descTecnica, evalData.descTecnica);
      if (evalData.descEmocional) playerInDir.descEmocional = mergeUniqueCsv(playerInDir.descEmocional, evalData.descEmocional);
      if (evalData.perfilRS) playerInDir.perfilRS = mergeUniqueCsv(playerInDir.perfilRS, evalData.perfilRS);
      if (evalData.rendimientoRS) playerInDir.rendimientoRS = evalData.rendimientoRS;
      if (evalData.tags && evalData.tags.length > 0) {
        const newTags = new Set([...(playerInDir.controlSeguimiento || []), ...evalData.tags]);
        playerInDir.controlSeguimiento = Array.from(newTags);
      }

      // Append/update match evaluation history
      if (!playerInDir.historialEvaluaciones) playerInDir.historialEvaluaciones = [];
      const repId = currentEditingReportId || 'temp';
      const existingIdx = playerInDir.historialEvaluaciones.findIndex(h => h.reportId === repId);
      const evalRecord = {
        reportId: repId,
        fecha: document.getElementById('reportDate')?.value || new Date().toISOString().split('T')[0],
        competicion: document.getElementById('reportCompeticion')?.value || 'Sin Especificar',
        equipo: teamName,
        dorsal: pNum,
        minutos: evalData.minutos || 0,
        rendimiento: evalData.rendimiento || 'C',
        rendimientoRS: evalData.rendimientoRS || 'C',
        potencial: evalData.potencial || '3',
        descFisica: evalData.descFisica || '',
        descTecnica: evalData.descTecnica || '',
        descEmocional: evalData.descEmocional || '',
        perfilRS: evalData.perfilRS || '',
        stats: evalData.stats || {}
      };

      if (existingIdx >= 0) playerInDir.historialEvaluaciones[existingIdx] = evalRecord;
      else playerInDir.historialEvaluaciones.push(evalRecord);

      recalculatePlayerAggregates(playerInDir);

      saveToFirebase('jugadores', playerInDir);
      saveState();
    }
  }

  function recalculatePlayerAggregates(player) {
    if (!player.historialEvaluaciones || player.historialEvaluaciones.length === 0) return;

    // Recalculate global stats
    const totalStats = {
      goles: 0, asistencias: 0, tirosPuerta: 0, tirosFuera: 0, pasesBuenos: 0, pasesMalos: 0,
      regatesExito: 0, regatesFallidos: 0, recuperaciones: 0, perdidas: 0, duelosGanados: 0,
      duelosPerdidos: 0, aereoGanado: 0, amarillas: 0, rojas: 0
    };

    let sumRend = 0, countRend = 0;
    let sumPot = 0, countPot = 0;
    let sumRendRS = 0, countRendRS = 0;
    const letterToNum = { 'A+': 5, 'A': 4, 'B': 3, 'C': 2, 'D': 1 };
    const minsByComp = {};

    player.historialEvaluaciones.forEach(h => {
      // Group minutes by competition
      const comp = h.competicion || 'Sin Especificar';
      if (!minsByComp[comp]) minsByComp[comp] = 0;
      minsByComp[comp] += (parseInt(h.minutos) || 0);

      // Sum stats
      if (h.stats) {
        for (const key in totalStats) {
          totalStats[key] += (h.stats[key] || 0);
        }
      }

      // Calculate averages
      if (h.rendimiento && letterToNum[h.rendimiento]) { sumRend += letterToNum[h.rendimiento]; countRend++; }
      if (h.potencial && !isNaN(parseInt(h.potencial))) { sumPot += parseInt(h.potencial); countPot++; }
      if (h.rendimientoRS && letterToNum[h.rendimientoRS]) { sumRendRS += letterToNum[h.rendimientoRS]; countRendRS++; }
    });

    player.stats = totalStats;
    player.minutosPorCompeticion = minsByComp;

    const numToLetter = (num) => {
      if (num >= 4.5) return 'A+';
      if (num >= 3.5) return 'A';
      if (num >= 2.5) return 'B';
      if (num >= 1.5) return 'C';
      return 'D';
    };

    if (countRend > 0) {
      const avg = sumRend / countRend;
      player.rendimientoAcumuladoAvgNum = avg.toFixed(1);
      player.rendimientoAcumulado = numToLetter(avg);
    }
    if (countPot > 0) {
      const avg = sumPot / countPot;
      player.potencialAvgNum = avg.toFixed(1);
      player.potencial = Math.round(avg).toString();
    }
    if (countRendRS > 0) {
      const avg = sumRendRS / countRendRS;
      player.rendimientoRSAvgNum = avg.toFixed(1);
      player.rendimientoRS = numToLetter(avg);
    }
  }

  function openPlayerMatchReportModal(team, type, idx) {
    const containerId = type === 'titular' ? `${team}TitularesRows` : `${team}SuplentesRows`;
    const rows = document.querySelectorAll(`#${containerId} .lineup-row`);
    const row = rows[idx];
    if (!row) return;

    const pNum = row.querySelector('input.num')?.value || (type === 'titular' ? idx + 1 : 12 + idx);
    const pName = row.querySelector('input.name')?.value.trim() || '';
    const pPos = row.querySelector('select.pos')?.value || 'MC';
    const teamName = document.getElementById(team === 'local' ? 'reportLocalTeam' : 'reportVisitanteTeam')?.value.trim() || (team === 'local' ? 'Equipo Local' : 'Equipo Visitante');

    const localOptionsDescTecnica = getOptionsDescTecnica(pPos);

    if (!state.matchPlayerEvaluations) state.matchPlayerEvaluations = {};
    const evalKey = `${currentEditingReportId || 'temp'}_${team}_${pNum}`;

    const currentMinsFromTimer = getCurrentMatchMinute();
    const defaultMins = type === 'titular' ? 90 : (currentMinsFromTimer > 0 ? (90 - currentMinsFromTimer) : 0);

    // Auto-load directory player traits if player exists in directory and match evaluation hasn't been created yet
    const playerInDir = (state.directory && state.directory.jugadores && pName) ? state.directory.jugadores.find(p => {
      const nameMatch = p.nombre && p.nombre.toLowerCase().trim() === pName.toLowerCase().trim();
      const numMatch = String(p.dorsal || p.numero || '').trim() === String(pNum).trim();
      const teamMatch = p.equipo && teamName && window.flexibleMatch(teamName, p.equipo);
      return nameMatch || (numMatch && teamMatch);
    }) : null;

    if (playerInDir && !state.matchPlayerEvaluations[evalKey]) {
      state.matchPlayerEvaluations[evalKey] = {
        rendimiento: playerInDir.rendimientoRS || 'C',
        potencial: playerInDir.potencial || '3',
        rendimientoRS: playerInDir.rendimientoRS || 'C',
        tags: playerInDir.tags || [],
        minutos: defaultMins,
        sustituido: false,
        comentarioGeneral: '',
        descFisica: playerInDir.descFisica || '',
        descTecnica: playerInDir.descTecnica || '',
        descEmocional: playerInDir.descEmocional || '',
        perfilRS: playerInDir.perfilRS || '',
        stats: {
          goles: 0, asistencias: 0, tirosPuerta: 0, tirosFuera: 0, pasesBuenos: 0, pasesMalos: 0,
          regatesExito: 0, regatesFallidos: 0, recuperaciones: 0, perdidas: 0, duelosGanados: 0,
          duelosPerdidos: 0, aereoGanado: 0, amarillas: 0, rojas: 0
        }
      };
    }

    const pEval = state.matchPlayerEvaluations[evalKey] || {
      rendimiento: 'C',
      potencial: '3',
      rendimientoRS: 'C',
      tags: [],
      minutos: defaultMins,
      sustituido: false,
      comentarioGeneral: '',
      descFisica: '',
      descTecnica: '',
      descEmocional: '',
      perfilRS: ''
    };

    const pStats = Object.assign({
      goles: 0, asistencias: 0, tirosPuerta: 0, tirosFuera: 0, pasesBuenos: 0, pasesMalos: 0,
      regatesExito: 0, regatesFallidos: 0, recuperaciones: 0, perdidas: 0, duelosGanados: 0,
      duelosPerdidos: 0, aereoGanado: 0, amarillas: 0, rojas: 0
    }, pEval.stats || {});

    const STAT_FIELDS = [
      { key: 'goles', label: 'Goles', icon: '⚽' },
      { key: 'asistencias', label: 'Asistencias', icon: '🅰️' },
      { key: 'tirosPuerta', label: 'Tiros a Puerta', icon: '🎯' },
      { key: 'tirosFuera', label: 'Tiros Fuera', icon: '🥅' },
      { key: 'pasesBuenos', label: 'Pases Buenos', icon: '🟢' },
      { key: 'pasesMalos', label: 'Pases Malos', icon: '🔴' },
      { key: 'regatesExito', label: 'Regates Éxito', icon: '🏃' },
      { key: 'regatesFallidos', label: 'Regates Fallidos', icon: '🚫' },
      { key: 'recuperaciones', label: 'Recuperaciones', icon: '🛡️' },
      { key: 'perdidas', label: 'Pérdidas', icon: '⚠️' },
      { key: 'duelosGanados', label: 'Duelos Ganados', icon: '⚔️' },
      { key: 'duelosPerdidos', label: 'Duelos Perdidos', icon: '❌' },
      { key: 'aereoGanado', label: 'Juego Aéreo', icon: '✈️' },
      { key: 'amarillas', label: 'Amarillas', icon: '🟨' },
      { key: 'rojas', label: 'Rojas', icon: '🟥' }
    ];

    const modalHTML = `
      <div class="player-match-modal-wrapper">
        <div class="player-match-header-bar">
          <div style="display: flex; align-items: center; gap: 12px;">
            <div style="background: rgba(255,255,255,0.2); width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 15px;">
              ${escapeHtml(pNum)}
            </div>
            <div>
              <h3 style="margin: 0; font-size: 16px; font-weight: 800; color: #fff;">Ficha de ${escapeHtml(pName || 'Jugador S/N')}</h3>
              <p style="margin: 2px 0 0; font-size: 11px; opacity: 0.9;">${escapeHtml(pPos)} | Dorsal ${escapeHtml(pNum)} | ${escapeHtml(teamName)}</p>
            </div>
          </div>
          <div style="display: flex; gap: 8px;">
            <button type="button" class="btn btn-secondary" id="btnClosePlayerMatchModal" style="font-size: 11px; padding: 6px 12px; background: rgba(255,255,255,0.15); color: #fff; border: 1px solid rgba(255,255,255,0.3);">Cerrar</button>
            <button type="button" class="btn btn-primary" id="btnSavePlayerMatchReport" style="font-size: 11px; padding: 6px 14px; background: #ffffff; color: #1d4ed8; font-weight: 800; border: none;">💾 Guardar Ficha</button>
          </div>
        </div>

        <div class="player-match-subtabs">
          <button type="button" class="player-match-subtab active" data-tab="pmTabDatos">DATOS PARTIDO JUGADOR</button>
          <button type="button" class="player-match-subtab" data-tab="pmTabDescripciones">📝 DESCRIPCIONES</button>
          <button type="button" class="player-match-subtab" data-tab="pmTabEstadisticas">📊 ESTADÍSTICAS INDIVIDUALES</button>
        </div>

        <!-- TAB 1: DATOS PARTIDO JUGADOR -->
        <div id="pmTabDatos" class="pm-tab-pane" style="padding: 16px; display: flex; flex-direction: column; gap: 16px;">
          
          <!-- LÍNEA 1: Rendimiento, Potencial, Rendimiento RS, Perfil RS -->
          <div style="display: flex; gap: 16px;">
            <!-- Rendimiento -->
            <div style="display: flex; flex-direction: column; align-items: center; justify-content: flex-start;">
              <div class="rating-score-title mb-2" style="text-align: center;">RENDIMIENTO</div>
              <div class="rs-pills-row" id="pmRendimientoGroup">
                <button type="button" class="rs-pill-btn ${pEval.rendimiento === 'A' ? 'active' : ''}" data-val="A" style="width: 38px; height: 38px; font-size: 14px;">A</button>
                <button type="button" class="rs-pill-btn ${pEval.rendimiento === 'B' ? 'active' : ''}" data-val="B" style="width: 38px; height: 38px; font-size: 14px;">B</button>
                <button type="button" class="rs-pill-btn ${pEval.rendimiento === 'C' ? 'active' : ''}" data-val="C" style="width: 38px; height: 38px; font-size: 14px;">C</button>
                <button type="button" class="rs-pill-btn ${pEval.rendimiento === 'D' ? 'active' : ''}" data-val="D" style="width: 38px; height: 38px; font-size: 14px;">D</button>
              </div>
            </div>

            <!-- Potencial -->
            <div style="display: flex; flex-direction: column; align-items: center; justify-content: flex-start;">
              <div class="rating-score-title mb-2" style="text-align: center; color: #ec4899;">POTENCIAL</div>
              <div class="rs-pills-row" id="pmPotencialGroup">
                ${[1, 2, 3, 4, 5].map(v => `<button type="button" class="rs-pill-btn-potencial ${pEval.potencial == v ? 'active' : ''}" data-val="${v}" style="width: 38px; height: 38px; font-size: 14px; border-radius: 50%; border: 2px solid ${pEval.potencial == v ? '#ec4899' : 'rgba(236,72,153,0.3)'}; color: ${pEval.potencial == v ? '#fff' : '#ec4899'}; background: ${pEval.potencial == v ? '#ec4899' : '#fff'}; cursor: pointer; transition: all 0.2s;">${v}</button>`).join('')}
              </div>
            </div>

            <!-- Rendimiento RS -->
            <div style="display: flex; flex-direction: column; align-items: center; justify-content: flex-start;">
              <div class="rating-score-title mb-2" style="text-align: center;">RENDIMIENTO RS</div>
              <div class="rs-pills-row" id="pmRendimientoRSGroup">
                <button type="button" class="rs-pill-btn ${pEval.rendimientoRS === 'A' ? 'active' : ''}" data-val="A" style="width: 38px; height: 38px; font-size: 14px;">A</button>
                <button type="button" class="rs-pill-btn ${pEval.rendimientoRS === 'B' ? 'active' : ''}" data-val="B" style="width: 38px; height: 38px; font-size: 14px;">B</button>
                <button type="button" class="rs-pill-btn ${pEval.rendimientoRS === 'C' ? 'active' : ''}" data-val="C" style="width: 38px; height: 38px; font-size: 14px;">C</button>
                <button type="button" class="rs-pill-btn ${pEval.rendimientoRS === 'D' ? 'active' : ''}" data-val="D" style="width: 38px; height: 38px; font-size: 14px;">D</button>
              </div>
            </div>

            <!-- Perfil RS -->
            <div class="form-group" style="margin: 0; flex-grow: 1; display: flex; flex-direction: column; justify-content: flex-start;">
              <label class="form-label" style="font-size: 10px; font-weight: 800; text-align: center; display: block; margin-bottom: 8px;">PERFIL DEL JUGADOR (RS)</label>
              ${buildFilteredPerfilKeepOpenHTML(pPos, 'pmPerfilRS')}
              <textarea id="pmPerfilRS" class="desc-card-textarea" style="height: 38px; margin-top: 4px; box-sizing: border-box;" placeholder="Perfil...">${escapeHtml(pEval.perfilRS)}</textarea>
            </div>
          </div>

          <!-- LÍNEA 2: Botones de 11 ideal y tags -->
          <div class="tags-control-grid" id="pmTagsGroup" style="grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));">
            ${['DESTACADO EQUIPO', '11 IDEAL', 'ERF', 'JULEN', 'LERINES', 'MAPA RS', 'KIROL SPORT', 'CLUB CONVENIDO', 'JUGADOR RS CENTRO'].map(tag => `
              <button type="button" class="tag-control-btn ${(pEval.tags || []).includes(tag) ? 'active' : ''}" data-tag="${escapeHtml(tag)}">
                ${escapeHtml(tag)}
              </button>
            `).join('')}
          </div>

          <!-- LÍNEA 3: Minutos, No Juega, Entra y Sale -->
          <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; align-items: center;">
            <div>
              <label class="form-label" style="font-size: 10px; font-weight: 800; display: block; text-align: center;">MINUTOS JUGADOS</label>
              <input type="number" id="pmMinutos" class="form-control" value="${pEval.minutos || 0}" min="0" max="120" style="width: 100%; font-weight: 800; text-align: center; height: 38px; box-sizing: border-box;">
            </div>
            <div style="padding-top: 18px;">
              <button type="button" class="tag-control-btn ${(pEval.tags || []).includes('NO JUEGA') ? 'active' : ''}" data-tag="NO JUEGA" style="margin: 0; width: 100%;">
                NO JUEGA
              </button>
            </div>
            <div style="padding-top: 18px;">
              <button type="button" class="btn-entra-toggle ${pEval.entra ? 'active' : ''}" id="pmBtnEntra" title="Marcar minuto de entrada" style="margin: 0; width: 100%; height: 38px; box-sizing: border-box; font-size: 11px;">
                <i data-lucide="log-in" style="width: 14px;"></i> ${pEval.entra ? ('ENTRÓ (' + (pEval.minutoEntrada || 0) + ')') : 'ENTRA'}
              </button>
            </div>
            <div style="padding-top: 18px;">
              <button type="button" class="btn-salir-toggle ${pEval.sustituido ? 'active' : ''}" id="pmBtnSalir" title="Marcar minuto de salida" style="margin: 0; width: 100%; height: 38px; box-sizing: border-box; font-size: 11px;">
                <i data-lucide="log-out" style="width: 14px;"></i> ${pEval.sustituido ? ('SUSTITUIDO (' + (pEval.minutoSalida || 0) + ')') : 'SALIR'}
              </button>
            </div>
          </div>

          <!-- LÍNEA 4: Comentario General (75%) y Posición Alternativa (25%) -->
          <div style="display: flex; gap: 16px;">
            <div class="form-group" style="flex: 3;">
              <label class="form-label" style="font-size: 10px; font-weight: 800;">COMENTARIO GENERAL</label>
              <textarea id="pmComentarioGeneral" class="form-control textarea-compact" style="height: 100px;" placeholder="Observaciones personales sobre el jugador...">${escapeHtml(pEval.comentarioGeneral)}</textarea>
            </div>
            <div class="form-group" style="flex: 1; display: flex; flex-direction: column;">
              <label class="form-label" style="font-size: 10px; font-weight: 800;">POSICIÓN ALTERNATIVA</label>
              <select id="pmPosicionAlternativa" class="form-control" style="font-weight: 800; text-align: center; height: 38px; margin-bottom: 4px;">
                <option value="">(Ninguna)</option>
                ${Object.keys(POSITION_TO_PERFIL_GROUP).map(pos => `<option value="${escapeHtml(pos)}" ${pEval.posicionAlternativa === pos ? 'selected' : ''}>${escapeHtml(pos)}</option>`).join('')}
              </select>
              <input type="text" id="pmPosicionAlternativaNota" class="form-control" placeholder="Añadir nota sobre la posición..." value="${escapeHtml(pEval.posicionAlternativaNota || '')}" style="height: 38px; font-size: 11px; flex: 1;">
            </div>
          </div>
        </div>

        <!-- TAB 3: DESCRIPCIONES -->
        <div id="pmTabDescripciones" class="pm-tab-pane hidden" style="padding: 16px 16px 180px 16px; overflow-y: auto; max-height: calc(90vh - 130px);">
          
          <div style="display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 20px;">
            
            <!-- COLUMN 1: FÍSICA -->
            <div>
              <h4 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 800; color: var(--primary-dark); border-bottom: 2px solid var(--border-light); padding-bottom: 4px;">1. DESCRIPCIÓN FÍSICA</h4>
              <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-bottom: 24px;">
                ${Object.keys(OPTIONS_DESC_FISICA).map(key => `
                  <div class="desc-card-box" style="padding: 8px;">
                    <div class="desc-card-title" style="font-size: 11px;">${escapeHtml(key)}</div>
                    ${buildKeepOpenDropdownHTML({ [key]: OPTIONS_DESC_FISICA[key] }, '+ Añadir...', `pmDescFisica_${key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}`)}
                    <textarea id="pmDescFisica_${key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}" class="desc-card-textarea" style="height: 38px; margin-top: 4px; box-sizing: border-box;" placeholder="...">${escapeHtml(pEval['descFisica_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()] || '')}</textarea>
                  </div>
                `).join('')}
              </div>
            </div>

            <!-- COLUMN 2: TÉCNICA -->
            <div>
              <h4 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 800; color: var(--primary-dark); border-bottom: 2px solid var(--border-light); padding-bottom: 4px;">2. DESCRIPCIÓN TÉCNICA</h4>
              <div style="display: flex; flex-direction: column; gap: 8px; margin-bottom: 24px;">
                ${Object.keys(localOptionsDescTecnica).map(key => `
                  <div class="desc-card-box" style="padding: 8px;">
                    <div class="desc-card-title" style="font-size: 11px;">${escapeHtml(key)}</div>
                    ${buildKeepOpenDropdownHTML({ [key]: localOptionsDescTecnica[key] }, '+ Añadir...', `pmDescTecnica_${key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}`)}
                    <textarea id="pmDescTecnica_${key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}" class="desc-card-textarea" style="height: 38px; margin-top: 4px; box-sizing: border-box;" placeholder="...">${escapeHtml(pEval['descTecnica_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()] || '')}</textarea>
                  </div>
                `).join('')}
              </div>
            </div>

            <!-- COLUMN 3: EMOCIONAL -->
            <div>
              <h4 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 800; color: var(--primary-dark); border-bottom: 2px solid var(--border-light); padding-bottom: 4px;">3. DESCRIPCIÓN EMOCIONAL</h4>
              <div style="display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px;">
                ${Object.keys(OPTIONS_DESC_EMOCIONAL).map(key => `
                  <div class="desc-card-box" style="padding: 8px;">
                    <div class="desc-card-title" style="font-size: 11px;">${escapeHtml(key)}</div>
                    ${buildKeepOpenDropdownHTML({ [key]: OPTIONS_DESC_EMOCIONAL[key] }, '+ Añadir...', `pmDescEmocional_${key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}`)}
                    <textarea id="pmDescEmocional_${key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}" class="desc-card-textarea" style="height: 38px; margin-top: 4px; box-sizing: border-box;" placeholder="...">${escapeHtml(pEval['descEmocional_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()] || '')}</textarea>
                  </div>
                `).join('')}
              </div>
            </div>

          </div>
        </div>

        <!-- TAB 2: ESTADÍSTICAS INDIVIDUALES -->
        <div id="pmTabEstadisticas" class="pm-tab-pane hidden" style="padding: 16px;">
          <!-- Summary Banner -->
          <div id="pmStatsSummaryBanner"></div>

          <!-- Stepper Counters Grid -->
          <div class="stats-grid-counters">
            ${STAT_FIELDS.map(f => `
              <div class="stat-counter-card">
                <div class="stat-counter-info">
                  <span class="stat-counter-icon">${f.icon}</span>
                  <span class="stat-counter-label">${escapeHtml(f.label)}</span>
                </div>
                <div class="stat-counter-controls">
                  <button type="button" class="btn-counter-stepper minus" data-stat="${f.key}" data-action="minus">-</button>
                  <span class="stat-counter-num" data-stat="${f.key}">${pStats[f.key] || 0}</span>
                  <button type="button" class="btn-counter-stepper plus" data-stat="${f.key}" data-action="plus">+</button>
                </div>
              </div>
            `).join('')}
          </div>
        </div>
      </div>
    `;

    showModal(`Ficha de Jugador: ${pName || 'S/N'}`, modalHTML, null);

    const modalFooter = document.querySelector('.modal-footer');
    if (modalFooter) modalFooter.style.display = 'none';

    const modalContent = document.getElementById('generalModalCard');
    if (modalContent) modalContent.classList.add('xlarge');

    // Pill Button Handlers
    modalContent.querySelectorAll('#pmRendimientoGroup .rs-pill-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        modalContent.querySelectorAll('#pmRendimientoGroup .rs-pill-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
      });
    });

    modalContent.querySelectorAll('#pmPotencialGroup .rs-pill-btn-potencial').forEach(btn => {
      btn.addEventListener('click', () => {
        modalContent.querySelectorAll('#pmPotencialGroup .rs-pill-btn-potencial').forEach(b => {
          b.classList.remove('active');
          b.style.background = '#fff';
          b.style.color = '#ec4899';
          b.style.borderColor = 'rgba(236,72,153,0.3)';
        });
        btn.classList.add('active');
        btn.style.background = '#ec4899';
        btn.style.color = '#fff';
        btn.style.borderColor = '#ec4899';
      });
    });

    // Custom Dropdown Handling
    modalContent.querySelectorAll('.custom-dropdown-trigger').forEach(trigger => {
      trigger.addEventListener('click', (e) => {
        e.stopPropagation();
        const menu = trigger.nextElementSibling;
        menu.classList.toggle('hidden');
      });
    });

    // (Global event listeners handle custom dropdown clicks and outside clicks)

    // Rendimiento RS Pills
    modalContent.querySelectorAll('#pmRendimientoRSGroup .rs-pill-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        modalContent.querySelectorAll('#pmRendimientoRSGroup .rs-pill-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
      });
    });

    // Tag Control Buttons Toggle
    modalContent.querySelectorAll('.tag-control-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        btn.classList.toggle('active');
      });
    });

    let minutoEntrada = pEval.minutoEntrada || 0;
    let minutoSalida = pEval.minutoSalida || 0;

    const btnEntra = modalContent.querySelector('#pmBtnEntra');
    const btnSalir = modalContent.querySelector('#pmBtnSalir');

    function recalculateMinutes() {
      const isEntra = btnEntra?.classList.contains('active');
      const isSalir = btnSalir?.classList.contains('active');
      const minsInput = modalContent.querySelector('#pmMinutos');
      if (!minsInput) return;

      if (isEntra && isSalir) {
        const played = Math.max(0, (minutoSalida || 90) - (minutoEntrada || 0));
        minsInput.value = played;
      } else if (isEntra && !isSalir) {
        const played = Math.max(0, 90 - (minutoEntrada || 0));
        minsInput.value = played;
      } else if (!isEntra && isSalir) {
        const played = Math.max(0, minutoSalida || 45);
        minsInput.value = played;
      } else {
        minsInput.value = type === 'titular' ? 90 : 0;
      }
    }

    btnEntra?.addEventListener('click', () => {
      const isNowEntra = !btnEntra.classList.contains('active');
      btnEntra.classList.toggle('active');
      if (isNowEntra) {
        const matchMin = getCurrentMatchMinute();
        minutoEntrada = matchMin > 0 ? matchMin : 60;
        btnEntra.innerHTML = `<i data-lucide="log-in" style="width: 14px;"></i> ENTRÓ (${minutoEntrada}')`;
      } else {
        minutoEntrada = 0;
        btnEntra.innerHTML = `<i data-lucide="log-in" style="width: 14px;"></i> ENTRA`;
      }
      if (window.lucide) window.lucide.createIcons();
      recalculateMinutes();
    });

    btnSalir?.addEventListener('click', () => {
      const isNowSalir = !btnSalir.classList.contains('active');
      btnSalir.classList.toggle('active');
      if (isNowSalir) {
        const matchMin = getCurrentMatchMinute();
        minutoSalida = matchMin > 0 ? matchMin : 75;
        btnSalir.innerHTML = `<i data-lucide="log-out" style="width: 14px;"></i> SUSTITUIDO (${minutoSalida}')`;
      } else {
        minutoSalida = 0;
        btnSalir.innerHTML = `<i data-lucide="log-out" style="width: 14px;"></i> SALIR`;
      }
      if (window.lucide) window.lucide.createIcons();
      recalculateMinutes();
    });

    // Subtabs Switcher
    modalContent.querySelectorAll('.player-match-subtab').forEach(btn => {
      btn.addEventListener('click', () => {
        modalContent.querySelectorAll('.player-match-subtab').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const targetId = btn.dataset.tab;
        modalContent.querySelectorAll('.pm-tab-pane').forEach(pane => {
          pane.classList.toggle('hidden', pane.id !== targetId);
        });
      });
    });

    // Live Stats Summary Banner Calculation
    function updateStatsSummaryBanner() {
      const totalPases = (pStats.pasesBuenos || 0) + (pStats.pasesMalos || 0);
      const pctPases = totalPases > 0 ? Math.round((pStats.pasesBuenos / totalPases) * 100) : 0;

      const totalRegates = (pStats.regatesExito || 0) + (pStats.regatesFallidos || 0);
      const pctRegates = totalRegates > 0 ? Math.round((pStats.regatesExito / totalRegates) * 100) : 0;

      const totalDuelos = (pStats.duelosGanados || 0) + (pStats.duelosPerdidos || 0);
      const pctDuelos = totalDuelos > 0 ? Math.round((pStats.duelosGanados / totalDuelos) * 100) : 0;

      const partGol = (pStats.goles || 0) + (pStats.asistencias || 0);
      const balanceRec = (pStats.recuperaciones || 0) - (pStats.perdidas || 0);

      const bannerHTML = `
        <div class="stats-summary-banner">
          <div class="stats-summary-card">
            <div class="stats-summary-title">EFECTIVIDAD PASE</div>
            <div class="stats-summary-value" style="color: ${pctPases >= 75 ? '#16a34a' : (pctPases >= 50 ? '#d97706' : '#dc2626')};">${pctPases}%</div>
          </div>
          <div class="stats-summary-card">
            <div class="stats-summary-title">ÉXITO REGATE</div>
            <div class="stats-summary-value" style="color: ${pctRegates >= 60 ? '#16a34a' : (pctRegates >= 40 ? '#d97706' : '#dc2626')};">${pctRegates}%</div>
          </div>
          <div class="stats-summary-card">
            <div class="stats-summary-title">DUELOS GANADOS</div>
            <div class="stats-summary-value" style="color: ${pctDuelos >= 50 ? '#16a34a' : '#dc2626'};">${pctDuelos}%</div>
          </div>
          <div class="stats-summary-card">
            <div class="stats-summary-title">PARTICIPACIÓN GOL</div>
            <div class="stats-summary-value" style="color: #2563eb;">${partGol}</div>
          </div>
          <div class="stats-summary-card">
            <div class="stats-summary-title">BALANCE REC/PÉR</div>
            <div class="stats-summary-value" style="color: ${balanceRec >= 0 ? '#16a34a' : '#dc2626'};">${balanceRec >= 0 ? '+' : ''}${balanceRec}</div>
          </div>
        </div>
      `;

      const bannerContainer = modalContent.querySelector('#pmStatsSummaryBanner');
      if (bannerContainer) bannerContainer.innerHTML = bannerHTML;
    }

    updateStatsSummaryBanner();

    // Counter Stepper Buttons (+ / -)
    modalContent.querySelectorAll('.btn-counter-stepper').forEach(btn => {
      btn.addEventListener('click', () => {
        const statKey = btn.dataset.stat;
        const action = btn.dataset.action;
        let currentVal = pStats[statKey] || 0;
        if (action === 'plus') {
          currentVal++;
        } else if (action === 'minus') {
          currentVal = Math.max(0, currentVal - 1);
        }
        pStats[statKey] = currentVal;

        const numSpan = modalContent.querySelector(`.stat-counter-num[data-stat="${statKey}"]`);
        if (numSpan) numSpan.textContent = currentVal;

        updateStatsSummaryBanner();
      });
    });

    // Close Button
    modalContent.querySelector('#btnClosePlayerMatchModal')?.addEventListener('click', () => {
      hideModal();
      if (modalFooter) modalFooter.style.display = '';
    });

    // Save Button
    modalContent.querySelector('#btnSavePlayerMatchReport')?.addEventListener('click', () => {
      const activeRSBtn = modalContent.querySelector('#pmRendimientoRSGroup .rs-pill-btn.active');
      const activeTags = Array.from(modalContent.querySelectorAll('.tag-control-btn.active')).map(b => b.dataset.tag);
      const isEntra = btnEntra?.classList.contains('active') || false;
      const isSalir = btnSalir?.classList.contains('active') || false;

      const evalObj = {
        name: pName,
        rendimiento: modalContent.querySelector('#pmRendimientoGroup .rs-pill-btn.active')?.dataset.val || 'C',
        potencial: modalContent.querySelector('#pmPotencialGroup .rs-pill-btn-potencial.active')?.dataset.val || '3',
        rendimientoRS: activeRSBtn ? activeRSBtn.dataset.val : 'C',
        tags: activeTags,
        entra: isEntra,
        minutoEntrada: isEntra ? minutoEntrada : 0,
        sustituido: isSalir,
        minutoSalida: isSalir ? minutoSalida : 0,
        minutos: parseInt(modalContent.querySelector('#pmMinutos').value) || 0,
        comentarioGeneral: modalContent.querySelector('#pmComentarioGeneral')?.value || '',
        posicionAlternativa: modalContent.querySelector('#pmPosicionAlternativa')?.value || '',
        posicionAlternativaNota: modalContent.querySelector('#pmPosicionAlternativaNota')?.value || '',
        perfilRS: modalContent.querySelector('#pmPerfilRS')?.value || '',
        stats: pStats
      };

      const allDescFisica = [];
      Object.keys(OPTIONS_DESC_FISICA).forEach(key => {
        const fieldKey = 'descFisica_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
        const val = modalContent.querySelector('#pmDescFisica_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase())?.value || '';
        evalObj[fieldKey] = val;
        if (val.trim()) allDescFisica.push(val.trim());
      });
      evalObj.descFisica = allDescFisica.join(', ');

      const allDescTecnica = [];
      Object.keys(localOptionsDescTecnica).forEach(key => {
        const fieldKey = 'descTecnica_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
        const val = modalContent.querySelector('#pmDescTecnica_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase())?.value || '';
        evalObj[fieldKey] = val;
        if (val.trim()) allDescTecnica.push(val.trim());
      });
      evalObj.descTecnica = allDescTecnica.join(', ');

      const allDescEmocional = [];
      Object.keys(OPTIONS_DESC_EMOCIONAL).forEach(key => {
        const fieldKey = 'descEmocional_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
        const val = modalContent.querySelector('#pmDescEmocional_' + key.replace(/[^a-zA-Z0-9]/g, '').toLowerCase())?.value || '';
        evalObj[fieldKey] = val;
        if (val.trim()) allDescEmocional.push(val.trim());
      });
      evalObj.descEmocional = allDescEmocional.join(', ');

      state.matchPlayerEvaluations[evalKey] = evalObj;

      // Sync to player's directory profile
      syncPlayerMatchReportToDirectory(pName, pNum, teamName, evalObj);
      saveToFirebase('directorio', state.directory); // Ensure persistence immediately

      // Persist the evaluation to the current Match Report in Firebase immediately
      if (currentEditingReportId) {
        const idx = state.reports.findIndex(r => r.id === currentEditingReportId);
        if (idx !== -1) {
          if (!state.reports[idx].playerEvaluations) state.reports[idx].playerEvaluations = {};
          state.reports[idx].playerEvaluations[evalKey] = evalObj;
          saveToFirebase('informes', state.reports[idx]);
        }
      }

      // Update pitch visually to reflect any new stat badges (like goals)
      if (typeof renderPitchPins === 'function') {
        renderPitchPins('local');
        renderPitchPins('visitante');
      }

      hideModal();
      if (modalFooter) modalFooter.style.display = '';
    });
  }

  function syncCoachDataToDirectory(coachName, coachRating, coachComentario, kirolSport, teamName, rivalTeam) {
    if (!coachName || !coachName.trim() || !state.directory) return;
    const nameTrim = coachName.trim();
    if (!state.directory.staff) state.directory.staff = [];

    // Find coach in staff directory matching name or team+cargo
    let staffObj = state.directory.staff.find(s => {
      const sName = (s.nombre || s.staff || '').trim().toLowerCase();
      const nMatch = sName === nameTrim.toLowerCase();
      const sTeam = (s.equipo || s.club || '').trim();
      const tMatch = teamName && sTeam && window.flexibleMatch(teamName, sTeam);
      const sCargo = (s.cargo || s.puesto || '').toUpperCase();
      const cMatch = !sCargo || sCargo.includes('ENTRENADOR') || sCargo.includes('TÉCNICO');
      return nMatch || (tMatch && cMatch);
    });

    // If not found, create new staff profile for coach in Directory
    if (!staffObj) {
      staffObj = {
        id: 'st_' + Date.now() + Math.random().toString(36).substr(2, 4),
        nombre: nameTrim,
        staff: nameTrim,
        cargo: 'Entrenador',
        equipo: teamName || '',
        nivel: 'Senior',
        tags: []
      };
      state.directory.staff.unshift(staffObj);
    }

    // Update staff properties
    staffObj.nota = coachRating || 3;
    staffObj.valoracion = coachRating || 3;
    if (coachComentario) staffObj.comentario = coachComentario;
    staffObj.kirolSport = !!kirolSport;

    if (kirolSport) {
      staffObj.tags = staffObj.tags || [];
      if (!staffObj.tags.includes('⚽ Kirol Sport')) {
        staffObj.tags.push('⚽ Kirol Sport');
      }
    }

    // Append/update match evaluation history in coach profile
    if (!staffObj.historialEvaluaciones) staffObj.historialEvaluaciones = [];
    const repId = currentEditingReportId || 'temp';
    const existingIdx = staffObj.historialEvaluaciones.findIndex(h => h.reportId === repId);
    const evalRecord = {
      reportId: repId,
      fecha: document.getElementById('reportDate')?.value || new Date().toISOString().split('T')[0],
      equipo: teamName,
      rival: rivalTeam,
      nota: coachRating,
      comentario: coachComentario,
      kirolSport: kirolSport
    };

    if (existingIdx >= 0) staffObj.historialEvaluaciones[existingIdx] = evalRecord;
    else staffObj.historialEvaluaciones.push(evalRecord);

    // Also update team object in directory
    if (teamName) {
      const teamObj = findTeamInDirectory(teamName);
      if (teamObj) {
        teamObj.entrenador = nameTrim;
        teamObj.entrenadorNota = coachRating;
        teamObj.entrenadorComentario = coachComentario;
        teamObj.entrenadorKirolSport = kirolSport;
      }
    }
  }
  function isSamePlayerName(nameA, nameB, teamA, teamB) {
    if (!nameA || !nameB) return false;
    const normalize = (s) => (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim().replace(/\s+/g, ' ');
    const a = normalize(nameA);
    const b = normalize(nameB);
    if (a === b) return true;

    const wordsA = a.split(' ');
    const wordsB = b.split(' ');

    const tA = normalize(teamA);
    const tB = normalize(teamB);

    const firstTwoMatch = wordsA.length >= 2 && wordsB.length >= 2 && wordsA[0] === wordsB[0] && wordsA[1] === wordsB[1];

    let thirdWordConflict = false;
    if (wordsA.length >= 3 && wordsB.length >= 3) {
      if (wordsA[2] !== wordsB[2]) thirdWordConflict = true;
    }

    if (tA && tB && (tA === tB || tA.includes(tB) || tB.includes(tA))) {
      if (firstTwoMatch && !thirdWordConflict) {
        return true;
      }
    }

    if (a.startsWith(b) || b.startsWith(a)) {
      if (firstTwoMatch && !thirdWordConflict) {
        return true;
      }
    }

    return false;
  }

  function syncMissingPositionsToDirectory(reportObj) {
    if (!state.directory || !state.directory.jugadores) return;

    const checkAndSync = (pObj, teamName) => {
      if (!pObj || !pObj.name || !pObj.pos) return;

      const foundPlayer = state.directory.jugadores.find(p => {
        const dName = (p.nombre || p.jugador || p.name || '');
        const dTeam = (p.equipo || p.equipoActual || '');
        return isSamePlayerName(dName, pObj.name, dTeam, teamName);
      });

      if (foundPlayer) {
        let posPri = foundPlayer.posicionPrincipal || foundPlayer.posicion || '';
        let updated = false;
        if (!posPri) {
          foundPlayer.posicionPrincipal = pObj.pos;
          updated = true;
        } else if (!foundPlayer.posicionSecundaria && foundPlayer.posicionPrincipal !== pObj.pos) {
          foundPlayer.posicionSecundaria = pObj.pos;
          updated = true;
        }
        if (updated) {
          saveToFirebase('jugadores', foundPlayer);
        }
      }
    };

    const checkAndSyncLocal = (pObj) => checkAndSync(pObj, reportObj.local);
    const checkAndSyncVisitante = (pObj) => checkAndSync(pObj, reportObj.visitante);

    (reportObj.localTitulares || []).forEach(checkAndSyncLocal);
    (reportObj.localSuplentes || []).forEach(checkAndSyncLocal);
    (reportObj.visitanteTitulares || []).forEach(checkAndSyncVisitante);
    (reportObj.visitanteSuplentes || []).forEach(checkAndSyncVisitante);
  }

  // Save Report Handler
  document.getElementById('btnSaveMatchReport')?.addEventListener('click', () => {
    try {
      const localTeam = document.getElementById('reportLocalTeam')?.value.trim() || 'Equipo Local';
      const visitanteTeam = document.getElementById('reportVisitanteTeam')?.value.trim() || 'Equipo Visitante';

      // Ensure active role tab states are saved
      saveCurrentTacticalRoleState('local');
      saveCurrentTacticalRoleState('visitante');

      const repId = currentEditingReportId || ('rep_' + Date.now());
      if (!state.matchPlayerEvaluations) state.matchPlayerEvaluations = {};

      ['local', 'visitante'].forEach(t => {
        const rows = document.querySelectorAll(`#${t}TitularesRows .lineup-row, #${t}SuplentesRows .lineup-row`);
        rows.forEach((r) => {
          const pNum = r.querySelector('input.num')?.value || r.querySelector('.num')?.value || '';
          const pName = r.querySelector('input.name')?.value.trim() || r.querySelector('.name')?.value.trim() || '';
          const evalKey = `${repId}_${t}_${pNum}`;
          if (state.matchPlayerEvaluations[evalKey]) {
            if (r.parentElement && r.parentElement.id && r.parentElement.id.includes('Titulares') && !state.matchPlayerEvaluations[evalKey].sustituido) {
              if (!state.matchPlayerEvaluations[evalKey].minutos) {
                state.matchPlayerEvaluations[evalKey].minutos = 90;
              }
            }
            if (pName) {
              syncPlayerMatchReportToDirectory(pName, pNum, t === 'local' ? localTeam : visitanteTeam, state.matchPlayerEvaluations[evalKey]);
            }
          }
        });
      });

      const reportObj = {
        id: repId,
        localTeam: localTeam,
        visitanteTeam: visitanteTeam,
        localScore: parseInt(document.getElementById('reportLocalScore')?.value) || 0,
        visitanteScore: parseInt(document.getElementById('reportVisitanteScore')?.value) || 0,
        date: document.getElementById('reportDate')?.value || new Date().toISOString().slice(0, 10),
        time: document.getElementById('reportTime')?.value || '20:00',
        estadio: document.getElementById('reportEstadio')?.value || '',
        clima: document.getElementById('reportClima')?.value || '',
        competicion: document.getElementById('reportCompeticion')?.value || '',
        categoria: document.getElementById('reportCategoria')?.value || '',
        federacion: document.getElementById('reportFederacion')?.value || '',

        localSystems: matchTacticalSystems.local,
        visitanteSystems: matchTacticalSystems.visitante,

        localIncludeCantera: document.getElementById('localIncludeCantera')?.checked || false,
        visitanteIncludeCantera: document.getElementById('visitanteIncludeCantera')?.checked || false,
        localFormation: matchTacticalSystems.local?.principal?.formation || document.getElementById('localFormationSelect')?.value || '1-4-3-3',
        visitanteFormation: matchTacticalSystems.visitante?.principal?.formation || document.getElementById('visitanteFormationSelect')?.value || '1-4-4-2',
        localDifficulty: getDifficultyRating('local'),
        visitanteDifficulty: getDifficultyRating('visitante'),
        localEstiloJuego: document.getElementById('localEstiloJuego')?.value || '',
        visitanteEstiloJuego: document.getElementById('visitanteEstiloJuego')?.value || '',

        localABPDetails: (function () {
          const details = {};
          ABP_KEYS.forEach(k => { details[k] = document.getElementById(`localABP_${k}`)?.value || ''; });
          return details;
        })(),
        visitanteABPDetails: (function () {
          const details = {};
          ABP_KEYS.forEach(k => { details[k] = document.getElementById(`visitanteABP_${k}`)?.value || ''; });
          return details;
        })(),
        localABP: (function () {
          const parts = [];
          ABP_KEYS.forEach(k => {
            const val = document.getElementById(`localABP_${k}`)?.value?.trim();
            if (val) parts.push(`${ABP_LABELS[k]}: ${val}`);
          });
          return parts.join('\n');
        })(),
        visitanteABP: (function () {
          const parts = [];
          ABP_KEYS.forEach(k => {
            const val = document.getElementById(`visitanteABP_${k}`)?.value?.trim();
            if (val) parts.push(`${ABP_LABELS[k]}: ${val}`);
          });
          return parts.join('\n');
        })(),
        localComentario: document.getElementById('localComentario')?.value || '',
        visitanteComentario: document.getElementById('visitanteComentario')?.value || '',

        localEntrenador: document.getElementById('localEntrenador')?.value || '',
        visitanteEntrenador: document.getElementById('visitanteEntrenador')?.value || '',
        localCoachRating: getCoachRating('local'),
        visitanteCoachRating: getCoachRating('visitante'),
        localComentarioEntrenador: document.getElementById('localComentarioEntrenador')?.value || '',
        visitanteComentarioEntrenador: document.getElementById('visitanteComentarioEntrenador')?.value || '',
        localKirolSport: document.getElementById('localBtnKirolSport')?.classList.contains('active') || false,
        visitanteKirolSport: document.getElementById('visitanteBtnKirolSport')?.classList.contains('active') || false,

        generalAnalysis: document.getElementById('reportGeneralAnalysis')?.value || '',
        localTitulares: matchTacticalSystems.local?.principal?.titulares || [],
        localSuplentes: matchTacticalSystems.local?.principal?.suplentes || [],
        visitanteTitulares: matchTacticalSystems.visitante?.principal?.titulares || [],
        visitanteSuplentes: matchTacticalSystems.visitante?.principal?.suplentes || [],

        playerEvaluations: Object.keys(state.matchPlayerEvaluations || {}).reduce((acc, key) => {
          if (key.startsWith(repId + '_')) {
            acc[key] = state.matchPlayerEvaluations[key];
          }
          return acc;
        }, {})
      };

      if (!Array.isArray(state.reports)) state.reports = [];

      if (currentEditingReportId) {
        const idx = state.reports.findIndex(r => r.id === currentEditingReportId);
        if (idx !== -1) state.reports[idx] = reportObj;
        else state.reports.unshift(reportObj);
      } else {
        state.reports.unshift(reportObj);
      }

      // Link reportId to corresponding match in state.matches and update match metadata
      if (Array.isArray(state.matches)) {
        const matchingMatch = state.matches.find(m =>
          (m.reportId === reportObj.id) ||
          (m.local && m.visitante && m.local.toLowerCase() === reportObj.localTeam.toLowerCase() && m.visitante.toLowerCase() === reportObj.visitanteTeam.toLowerCase())
        );
        if (matchingMatch) {
          matchingMatch.reportId = reportObj.id;
          matchingMatch.competicion = reportObj.competicion;
          matchingMatch.categoria = reportObj.categoria;
          matchingMatch.estadio = reportObj.estadio;
          matchingMatch.fecha = reportObj.date;
          matchingMatch.hora = reportObj.time;
          matchingMatch.estado = 'visto';
          saveToFirebase('partidos', matchingMatch);
        }
      }

      // Also auto-add/update players into directory
      if (state.directory && Array.isArray(state.directory.jugadores)) {
        [...reportObj.localTitulares, ...reportObj.visitanteTitulares].forEach(p => {
          if (p.name && !/^\d/.test(p.name.trim()) && !state.directory.jugadores.some(j => j.nombre && j.nombre.toLowerCase() === p.name.toLowerCase())) {
            state.directory.jugadores.push({
              id: 'j_' + Date.now() + Math.random().toString(36).substr(2, 4),
              nombre: p.name,
              equipo: reportObj.localTitulares.includes(p) ? reportObj.localTeam : reportObj.visitanteTeam,
              posicion: p.pos || '',
              ano: '2006',
              categoria: reportObj.categoria || 'Senior',
              nivel: 'Prospecto'
            });
          }
        });
      }

      // Sync team playstyle and ABP to team profiles in directory
      syncTeamStyleToDirectory(reportObj.localTeam, reportObj.localEstiloJuego, reportObj.localABP);
      syncTeamStyleToDirectory(reportObj.visitanteTeam, reportObj.visitanteEstiloJuego, reportObj.visitanteABP);

      // Sync coach data to coach staff profile and team profile in directory
      if (reportObj.localEntrenador) {
        syncCoachDataToDirectory(
          reportObj.localEntrenador,
          reportObj.localCoachRating,
          reportObj.localComentarioEntrenador,
          reportObj.localKirolSport,
          reportObj.localTeam,
          reportObj.visitanteTeam
        );
      }
      if (reportObj.visitanteEntrenador) {
        syncCoachDataToDirectory(
          reportObj.visitanteEntrenador,
          reportObj.visitanteCoachRating,
          reportObj.visitanteComentarioEntrenador,
          reportObj.visitanteKirolSport,
          reportObj.visitanteTeam,
          reportObj.localTeam
        );
      }

      syncMissingPositionsToDirectory(reportObj);

      saveToFirebase('informes', reportObj);
      saveState();

      if (typeof showNotification === 'function') {
        showNotification('¡Informe Técnico de Partido guardado con éxito y sincronizado en la nube!', 'success');
      } else {
        alert('¡Informe Técnico de Partido guardado con éxito!');
      }

      closeReportEditor();
      if (typeof renderPartidosList === 'function') {
        renderPartidosList();
      }
    } catch (err) {
      console.error('Error al guardar el informe técnico de partido:', err);
      alert('Error al guardar el informe: ' + err.message);
    }
  });

