  function deleteDirectoryItem(tabName, itemId) {
    if (!tabName || itemId === undefined || itemId === null) return;
    if (!state.directory) state.directory = {};

    const targetStr = String(itemId).trim().toLowerCase();

    // Find the item object BEFORE filtering (we need its real .id for Firebase)
    let itemObj = null;
    if (Array.isArray(state.directory[tabName])) {
      itemObj = state.directory[tabName].find(i =>
        i &&
        (
          (i.id !== undefined && String(i.id).trim().toLowerCase() === targetStr) ||
          (i.codigo !== undefined && String(i.codigo).trim().toLowerCase() === targetStr) ||
          (i.nombre !== undefined && String(i.nombre).trim().toLowerCase() === targetStr)
        )
      );
    }

    // === TOMBSTONE: register deletion permanently so seeding won't re-create it ===
    if (!state.deletedTombstones) state.deletedTombstones = {};
    if (!state.deletedTombstones[tabName]) state.deletedTombstones[tabName] = { ids: [], names: [] };
    const tomb = state.deletedTombstones[tabName];
    if (itemObj) {
      if (itemObj.id != null && !tomb.ids.includes(String(itemObj.id))) tomb.ids.push(String(itemObj.id));
      if (itemObj.nombre && !tomb.names.includes(itemObj.nombre.toLowerCase().trim())) tomb.names.push(itemObj.nombre.toLowerCase().trim());
      if (itemObj.seleccion && !tomb.names.includes(itemObj.seleccion.toLowerCase().trim())) tomb.names.push(itemObj.seleccion.toLowerCase().trim());
    }
    // Also tombstone by the raw itemId passed
    if (!tomb.ids.includes(String(itemId).trim())) tomb.ids.push(String(itemId).trim());

    // Remove from local state
    if (Array.isArray(state.directory[tabName])) {
      state.directory[tabName] = state.directory[tabName].filter(item => {
        if (!item) return false;
        const matchId = item.id !== undefined && item.id !== null && String(item.id).trim().toLowerCase() === targetStr;
        const matchCode = item.codigo !== undefined && item.codigo !== null && String(item.codigo).trim().toLowerCase() === targetStr;
        const matchName = item.nombre !== undefined && item.nombre !== null && String(item.nombre).trim().toLowerCase() === targetStr;
        const matchObj = itemObj && item === itemObj;
        return !matchId && !matchCode && !matchName && !matchObj;
      });
    }

    // Delete from Firebase immediately and directly using the real item ID
    if (db) {
      setFirebaseHeaderStatus('syncing');
      const idsToDelete = new Set();
      idsToDelete.add(String(itemId).trim());
      if (itemObj && itemObj.id != null) idsToDelete.add(String(itemObj.id).trim());
      if (itemObj && itemObj.codigo != null) idsToDelete.add(String(itemObj.codigo).trim());

      const batch = db.batch();
      idsToDelete.forEach(id => {
        if (id) batch.delete(db.collection(tabName).doc(id));
      });
      batch.commit()
        .then(() => {
          console.log(`🔥 Borrado de Firebase: ${tabName} / [${[...idsToDelete].join(', ')}]`);
          setFirebaseHeaderStatus('synced');
        })
        .catch(err => {
          console.error(`Error borrando de Firebase (${tabName}):`, err);
          setFirebaseHeaderStatus('error');
        });
    }

    saveState();
  }

