  function cleanOrphanPlayersFromAllTeams() {
    if (!state || !state.directory || !Array.isArray(state.directory.equipos)) return 0;
    const validPlayers = state.directory.jugadores || [];
    const validNamesSet = new Set(validPlayers.map(p => (p.nombre || p.jugador || p.name || '').toLowerCase().trim()).filter(Boolean));

    let cleanedCount = 0;
    state.directory.equipos.forEach(eq => {
      let modified = false;
      const eqNameLower = (eq.nombre || '').toLowerCase().trim();
      
      if (Array.isArray(eq.plantilla)) {
        const origLen = eq.plantilla.length;
        eq.plantilla = eq.plantilla.filter(item => {
          const nameStr = (typeof item === 'string' ? item : (item.nombre || item.jugador || item.name || '')).toLowerCase().trim();
          return validNamesSet.has(nameStr);
        });
        if (eq.plantilla.length < origLen) {
          modified = true;
        }
      } else {
        eq.plantilla = [];
      }

      if (eqNameLower && validPlayers.length) {
        validPlayers.forEach(p => {
          const pEq = (p.equipoPrincipal || p.equipo || '').toLowerCase().trim();
          if (pEq === eqNameLower) {
            const pName = p.nombre || p.jugador || p.name || '';
            if (pName && !eq.plantilla.some(item => (typeof item === 'string' ? item : (item.nombre || '')).toLowerCase().trim() === pName.toLowerCase().trim())) {
              eq.plantilla.push(pName);
              modified = true;
            }
          }
        });
      }

      if (modified) {
        cleanedCount++;
        saveToFirebase('equipos', eq);
      }
    });

    if (cleanedCount > 0) {
      saveState();
    }
    return cleanedCount;
  }

  function getFederationSelectionBaseName(fedName) {
    if (!fedName) return 'Regional';
    const nameLower = fedName.toLowerCase();

    if (nameLower.includes('rfef') || nameLower.includes('española') || nameLower.includes('españa')) return 'España';
    if (nameLower.includes('navarr') || nameLower.includes('fnf')) return 'Navarra';
    if (nameLower.includes('aragon') || nameLower.includes('aragón') || nameLower.includes('farag') || nameLower.includes('faf')) return 'Aragón';
    if (nameLower.includes('rioja') || nameLower.includes('frf')) return 'La Rioja';
    if (nameLower.includes('vasca') || nameLower.includes('euskadi') || nameLower.includes('pais vasco') || nameLower.includes('país vasco') || nameLower.includes('eff')) return 'País Vasco';
    if (nameLower.includes('madrid') || nameLower.includes('rffm')) return 'Madrid';
    if (nameLower.includes('catalana') || nameLower.includes('cataluña') || nameLower.includes('catalunya') || nameLower.includes('fcaf') || nameLower.includes('fcf')) return 'Cataluña';
    if (nameLower.includes('valencian') || nameLower.includes('comunitat valenciana') || nameLower.includes('ffcv')) return 'C. Valenciana';
    if (nameLower.includes('andaluz') || nameLower.includes('andalucía') || nameLower.includes('rfaf') || nameLower.includes('fand')) return 'Andalucía';
    if (nameLower.includes('galleg') || nameLower.includes('galicia') || nameLower.includes('fgf')) return 'Galicia';
    if (nameLower.includes('asturia') || nameLower.includes('rffpa')) return 'Asturias';
    if (nameLower.includes('canta') || nameLower.includes('cántab') || nameLower.includes('cantab') || nameLower.includes('rfcf')) return 'Cantabria';
    if (nameLower.includes('castilla y león') || nameLower.includes('castellano-leonesa') || nameLower.includes('castilla leon') || nameLower.includes('fcylf')) return 'Castilla y León';
    if (nameLower.includes('castilla-la mancha') || nameLower.includes('castilla la mancha') || nameLower.includes('ffcm')) return 'Castilla-La Mancha';
    if (nameLower.includes('extremad') || nameLower.includes('fexf')) return 'Extremadura';
    if (nameLower.includes('murcia') || nameLower.includes('ffrm')) return 'Murcia';
    if (nameLower.includes('balear') || nameLower.includes('balears') || nameLower.includes('ffib')) return 'Baleares';
    if (nameLower.includes('canaria') || nameLower.includes('canarias') || nameLower.includes('fcan')) return 'Canarias';
    if (nameLower.includes('ceuta') || nameLower.includes('ceutí') || nameLower.includes('ffce')) return 'Ceuta';
    if (nameLower.includes('melilla') || nameLower.includes('melillense') || nameLower.includes('rfmf')) return 'Melilla';

    return fedName.replace(/^(real\s+|federación\s+(de\s+fútbol\s+de\s+la\s+|de\s+fútbol\s+de\s+|de\s+|del\s+)?|federació\s+)/i, '').trim();
  }

  function ensureFederacionesSeleccionesSeeded() {
    if (!state || !state.directory) return;
    if (!state.directory.selecciones) state.directory.selecciones = [];

    const federaciones = state.directory.federaciones || [];
    if (federaciones.length === 0) return;

    const requestedCategories = [
      { cat: 'Sub16', sexo: 'Masculino', label: 'Sub16 Masculina' },
      { cat: 'Sub14', sexo: 'Masculino', label: 'Sub14 Masculina' },
      { cat: 'Sub12', sexo: 'Masculino', label: 'Sub12 Masculina' },
      { cat: 'Sub12', sexo: 'Femenino', label: 'Sub12 Femenina' },
      { cat: 'Sub15', sexo: 'Femenino', label: 'Sub15 Femenina' },
      { cat: 'Sub17', sexo: 'Femenino', label: 'Sub17 Femenina' }
    ];

    let newCount = 0;
    let updatedCount = 0;

    // 1. First update ALL existing selecciones names to format cleanly: "[Comunidad] [Categoría] [Sexo] 26/27"
    state.directory.selecciones.forEach(s => {
      if (!s) return;
      const fedStr = s.federacion || s.nombre || '';
      const baseName = getFederationSelectionBaseName(fedStr);
      const cat = s.categoria || 'Sub16';
      const sexo = s.sexo || 'Masculino';
      const sexoLabel = sexo === 'Femenino' ? 'Femenina' : 'Masculina';

      const cleanName = `${baseName} ${cat} ${sexoLabel} 26/27`;

      if (s.nombre !== cleanName || s.seleccion !== cleanName || s.temporada !== '26/27') {
        s.nombre = cleanName;
        s.seleccion = cleanName;
        s.temporada = '26/27';
        saveToFirebase('selecciones', s);
        updatedCount++;
      }
    });

    // 2. Deduplicate selecciones by name
    const uniqueSelecciones = [];
    const seenNames = new Set();

    state.directory.selecciones.forEach(s => {
      if (!s || !s.nombre) return;
      const cleanLower = s.nombre.toLowerCase().trim();
      if (!seenNames.has(cleanLower)) {
        seenNames.add(cleanLower);
        uniqueSelecciones.push(s);
      } else {
        if (s.id) deleteFromFirebase('selecciones', s.id);
      }
    });

    state.directory.selecciones = uniqueSelecciones;

    // 3. Ensure all requested categories exist for every federation
    federaciones.forEach(fed => {
      const fedFullName = fed.nombre || fed.federacion;
      if (!fedFullName) return;
      const baseName = getFederationSelectionBaseName(fedFullName);

      requestedCategories.forEach(req => {
        const selFullName = `${baseName} ${req.label} 26/27`;
        const selFullNameClean = selFullName.toLowerCase().trim();

        const exists = state.directory.selecciones.some(s =>
          s && ((s.nombre || s.seleccion || '').toLowerCase().trim() === selFullNameClean ||
            ((s.federacion || '').toLowerCase().trim() === fedFullName.toLowerCase().trim() &&
              (s.categoria || '').toLowerCase().trim() === req.cat.toLowerCase() &&
              (s.sexo || '').toLowerCase().trim() === req.sexo.toLowerCase() &&
              (s.temporada || '').includes('26/27')))
        );

        if (!exists) {
          // === CHECK TOMBSTONE: don't re-create if user deleted this selección ===
          if (!state.deletedTombstones) state.deletedTombstones = {};
          const tomb = state.deletedTombstones['selecciones'] || { ids: [], names: [] };
          const nameLower = selFullName.toLowerCase().trim();
          const isTombstoned = tomb.names.includes(nameLower);
          if (isTombstoned) return; // User deleted this — never re-create

          const newSel = {
            id: 'sel_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
            nombre: selFullName,
            seleccion: selFullName,
            federacion: fedFullName,
            categoria: req.cat,
            sexo: req.sexo,
            temporada: '26/27',
            escudo: fed.escudo || fed.logo || '',
            logo: fed.escudo || fed.logo || '',
            colorPrimary: fed.colorPrimary || fed.colorPrimario || '#2563eb',
            colorSecondary: fed.colorSecondary || fed.colorSecundario || '#ffffff',
            jugadores: [],
            staff: []
          };
          state.directory.selecciones.push(newSel);
          saveToFirebase('selecciones', newSel);
          newCount++;
        }
      });
    });

    if (newCount > 0 || updatedCount > 0) {
      saveState();
    }
  }

  function wipeAragonData() {
    if (!state.directory) return;
    if (state.directory.aragonWiped) return; // run only once

    console.log("🧹 Wiping Aragon data from Firebase...");
    let wipeCount = 0;

    // Wipe clubs
    if (Array.isArray(state.directory.clubes)) {
      state.directory.clubes.forEach(c => {
        if (!c) return;
        const com = (c.comunidad || '').toLowerCase().trim();
        const fed = (c.federacion || '').toLowerCase().trim();
        if (com === 'aragón' || com === 'aragon' || fed.includes('aragon') || fed.includes('fargf') || (c.id && c.id.startsWith('c_fa_'))) {
          if (c.id && db) db.collection('clubes').doc(String(c.id)).delete().catch(() => { });
          wipeCount++;
        }
      });
      // also filter locally to not show them
      state.directory.clubes = state.directory.clubes.filter(c => {
        if (!c) return true;
        const com = (c.comunidad || '').toLowerCase().trim();
        const fed = (c.federacion || '').toLowerCase().trim();
        return !(com === 'aragón' || com === 'aragon' || fed.includes('aragon') || fed.includes('fargf') || (c.id && c.id.startsWith('c_fa_')));
      });
    }

    // Wipe teams
    if (Array.isArray(state.directory.equipos)) {
      state.directory.equipos.forEach(eq => {
        if (!eq) return;
        const fed = (eq.federacion || '').toLowerCase().trim();
        if (fed.includes('aragon') || fed.includes('fargf')) {
          if (eq.id && db) db.collection('equipos').doc(String(eq.id)).delete().catch(() => { });
          wipeCount++;
        }
      });
      state.directory.equipos = state.directory.equipos.filter(eq => {
        if (!eq) return true;
        const fed = (eq.federacion || '').toLowerCase().trim();
        return !(fed.includes('aragon') || fed.includes('fargf'));
      });
    }

    // Wipe selecciones
    if (Array.isArray(state.directory.selecciones)) {
      state.directory.selecciones.forEach(s => {
        if (!s) return;
        const fed = (s.federacion || '').toLowerCase().trim();
        if (fed.includes('aragon') || fed.includes('fargf')) {
          if (s.id && db) db.collection('selecciones').doc(String(s.id)).delete().catch(() => { });
          wipeCount++;
        }
      });
      state.directory.selecciones = state.directory.selecciones.filter(s => {
        if (!s) return true;
        const fed = (s.federacion || '').toLowerCase().trim();
        return !(fed.includes('aragon') || fed.includes('fargf'));
      });
    }

    // Wipe federaciones
    if (Array.isArray(state.directory.federaciones)) {
      state.directory.federaciones.forEach(f => {
        if (!f) return;
        const fn = (f.nombre || '').toLowerCase();
        if (fn.includes('aragon') || fn.includes('fargf')) {
          if (f.id && db) db.collection('federaciones').doc(String(f.id)).delete().catch(() => { });
          wipeCount++;
        }
      });
      state.directory.federaciones = state.directory.federaciones.filter(f => {
        if (!f) return true;
        const fn = (f.nombre || '').toLowerCase();
        return !(fn.includes('aragon') || fn.includes('fargf'));
      });
    }

    state.directory.aragonWiped = true;
    if (wipeCount > 0) {
      console.log(`✅ ${wipeCount} items de Aragón eliminados de Firebase.`);
      saveState();
    }
  }

  function getOrCreateClub(clubName, comunidad = 'Nacional', federacion = 'RFEF') {
    if (!state.directory) state.directory = {};
    if (!state.directory.clubes) state.directory.clubes = [];
    const cleanName = String(clubName || '').replace(/"[ABC]"/g, '').replace(/ [ABC]$/, '').trim();
    if (!cleanName) return null;

    const slugId = 'club_' + cleanName.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '');

    let clubMatch = state.directory.clubes.find(c =>
      c && (
        String(c.id) === String(slugId) ||
        (c.nombre && String(c.nombre).toLowerCase().trim() === cleanName.toLowerCase()) ||
        (c.equipo && String(c.equipo).toLowerCase().trim() === cleanName.toLowerCase())
      )
    );

    if (!clubMatch) {
      clubMatch = {
        id: slugId,
        nombre: cleanName,
        equipo: cleanName,
        comunidad: comunidad,
        pais: 'España',
        federacion: federacion
      };
      state.directory.clubes.unshift(clubMatch);
      if (db) db.collection('clubes').doc(String(slugId)).set(clubMatch, { merge: true }).catch(() => { });
    } else {
      if (clubMatch.id !== slugId) {
        clubMatch.id = slugId;
      }
    }
    return clubMatch;
  }

  function deduplicateDirectoryData() {
    if (!state.directory) return;
    let modified = false;

    // 1. Deduplicate Clubes
    if (Array.isArray(state.directory.clubes) && state.directory.clubes.length > 0) {
      const clubMap = new Map();
      const duplicateClubIds = new Set();
      const uniqueClubes = [];

      state.directory.clubes.forEach(club => {
        if (!club) return;
        const normName = String(club.nombre || club.equipo || '').toLowerCase().trim();
        if (!normName) return;

        // Filter out phantom concatenated clubs (e.g. "Zaragoza-Racing Club, UD Montecarlo")
        if (normName.includes(',') || normName.includes(';')) {
          if (club.id) duplicateClubIds.add(String(club.id));
          return;
        }

        if (!clubMap.has(normName)) {
          clubMap.set(normName, club);
          uniqueClubes.push(club);
        } else {
          const primaryClub = clubMap.get(normName);
          if (club.id && String(club.id) !== String(primaryClub.id)) {
            duplicateClubIds.add(String(club.id));
          }
        }
      });

      if (duplicateClubIds.size > 0) {
        modified = true;
        console.log(`🧹 Eliminando ${duplicateClubIds.size} clubes duplicados de Firestore y memoria...`);
        state.directory.clubes = uniqueClubes;

        if (db) {
          duplicateClubIds.forEach(id => {
            db.collection('clubes').doc(id).delete().catch(e => console.warn('Error borrando club duplicado:', id, e));
          });
        }

        // Re-link teams
        if (Array.isArray(state.directory.equipos)) {
          state.directory.equipos.forEach(eq => {
            if (!eq) return;
            const eqClubName = String(eq.clubVinculado || eq.club || '').toLowerCase().trim();
            if (eqClubName && clubMap.has(eqClubName)) {
              const primaryC = clubMap.get(eqClubName);
              if (eq.clubId !== primaryC.id || eq.club !== primaryC.nombre) {
                eq.clubId = primaryC.id;
                eq.club = primaryC.nombre;
                if (db) db.collection('equipos').doc(String(eq.id)).update({ clubId: primaryC.id, club: primaryC.nombre }).catch(() => { });
              }
            }
          });
        }
      }
    }

    // 2. Deduplicate Equipos
    if (Array.isArray(state.directory.equipos) && state.directory.equipos.length > 0) {
      const teamMap = new Map();
      const duplicateTeamIds = new Set();
      const uniqueEquipos = [];

      state.directory.equipos.forEach(eq => {
        if (!eq) return;
        const rawName = String(eq.nombre || eq.equipo || '').trim();
        const normName = rawName.replace(/\./g, '').toLowerCase();
        const normComp = String(eq.competicion || '').toLowerCase().trim();
        const normGrup = String(eq.grupo || '').toLowerCase().trim();
        const key = `${normName}|${normComp}|${normGrup}`;

        if (!normName) return;

        if (!teamMap.has(key)) {
          if (rawName.includes('.')) {
            eq.nombre = rawName.replace(/\./g, '');
            eq.equipo = eq.nombre;
            if (db) db.collection('equipos').doc(String(eq.id)).update({ nombre: eq.nombre, equipo: eq.nombre }).catch(() => {});
          }
          teamMap.set(key, eq);
          uniqueEquipos.push(eq);
        } else {
          const primaryTeam = teamMap.get(key);
          if (eq.id && String(eq.id) !== String(primaryTeam.id)) {
            if (primaryTeam.nombre && primaryTeam.nombre.includes('.')) {
              primaryTeam.nombre = primaryTeam.nombre.replace(/\./g, '');
              primaryTeam.equipo = primaryTeam.nombre;
              if (db) db.collection('equipos').doc(String(primaryTeam.id)).update({ nombre: primaryTeam.nombre, equipo: primaryTeam.nombre }).catch(() => {});
            }
            duplicateTeamIds.add(String(eq.id));
          }
        }
      });

      if (duplicateTeamIds.size > 0) {
        modified = true;
        console.log(`🧹 Eliminando ${duplicateTeamIds.size} equipos duplicados de Firestore y memoria...`);
        state.directory.equipos = uniqueEquipos;

        if (db) {
          duplicateTeamIds.forEach(id => {
            db.collection('equipos').doc(id).delete().catch(e => console.warn('Error borrando equipo duplicado:', id, e));
          });
        }
      }
    }

    if (modified) {
      saveState();
    }
  }

  function migrateFederacionesClubs() {
    if (!state.directory || !Array.isArray(state.directory.clubes)) return;
    if (state.directory.federacionesClubsMigrated) return;

    const FAF = 'FAF - Real Federación Aragonesa de Fútbol';
    const FNF = 'FNF - Federación Navarra de Fútbol';
    let changed = 0;

    state.directory.clubes.forEach(club => {
      if (!club) return;
      const com = (club.comunidad || '').toLowerCase().trim();
      const fed = (club.federacion || '').toLowerCase().trim();

      if (com === 'aragón' || com === 'aragon' || fed.includes('aragon') || fed.includes('fargf') || (club.id && club.id.startsWith('c_fa_'))) {
        if (club.federacion !== FAF) {
          club.federacion = FAF;
          if (db) db.collection('clubes').doc(String(club.id)).update({ federacion: FAF }).catch(() => { });
          changed++;
        }
      } else if (com === 'navarra' || fed.includes('navarra') || fed.includes('fnf') || (club.id && club.id.startsWith('club_fnf_'))) {
        if (club.federacion !== FNF) {
          club.federacion = FNF;
          if (db) db.collection('clubes').doc(String(club.id)).update({ federacion: FNF }).catch(() => { });
          changed++;
        }
      }
    });

    state.directory.federacionesClubsMigrated = true;
    if (changed > 0) {
      console.log(`✅ Federaciones actualizadas en ${changed} clubes`);
      saveState();
    }
  }

